function normalizeAt(value, anchorDate, anchorTime) {
  if (!value) return null;
  const text = String(value).trim().replace(" ", "T");
  if (/^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?$/.test(text)) return text.slice(0, 16);
  if (!validTime(text)) throw new Error("reminder_at must be HH:MM or YYYY-MM-DDTHH:MM");
  const sameDay = localDateTime(anchorDate, text);
  if (!sameDay) throw new Error("A timed reminder requires an event date and time");
  return text > anchorTime ? shiftWallClock(anchorDate, text, -24 * 60) : sameDay;
}

function offsetFromAt(anchorAt, reminderAt) {
  const anchor = wallClockMinutes(anchorAt);
  const reminder = wallClockMinutes(reminderAt);
  if (anchor === null || reminder === null) throw new Error("Invalid reminder date-time");
  return integerInRange(anchor - reminder, "reminder_offset_minutes");
}

function reminderAt(anchorAt, offsetMinutes) {
  const [date, time] = anchorAt.split("T");
  return shiftWallClock(date, time, -offsetMinutes);
}

function reminderAnchor(input) {
  const scheduledDate = first(input, "scheduled_date", "scheduledDate", "requested_date", "requestedDate");
  const scheduledStart = String(first(input, "scheduled_start", "scheduledStart", "requested_time", "requestedTime") || "").slice(0, 5);
  if (validDate(scheduledDate) && validTime(scheduledStart)) {
    return { kind: "execution", date: scheduledDate, time: scheduledStart, at: localDateTime(scheduledDate, scheduledStart) };
  }
  const deadline = first(input, "deadline");
  const deadlineTime = String(first(input, "deadline_time", "deadlineTime") || "").slice(0, 5);
  if (validDate(deadline) && validTime(deadlineTime)) {
    return { kind: "deadline", date: deadline, time: deadlineTime, at: localDateTime(deadline, deadlineTime) };
  }
  return null;
}

function extractActions(text) {
  return ACTION_PATTERNS
    .map(([action, pattern]) => ({ action, index: String(text).search(pattern) }))
    .filter(({ index }) => index >= 0)
    .sort((left, right) => left.index - right.index)
    .map(({ action }) => action);
}

function normalizedActions(input, text) {
  const supplied = first(input, "pre_event_actions", "preEventActions");
  if (Array.isArray(supplied)) {
    return [...new Set(supplied.map((item) => String(item || "").trim()).filter(Boolean))].slice(0, 20);
  }
  return extractActions(text);
}

function inferTransportation(input, text) {
  const supplied = String(first(input, "transportation", "transport_mode", "transportMode") || "").trim().toLowerCase();
  if (supplied) return ({ subway: "metro", car: "drive", driving: "drive", walking: "walk", bicycle: "bike", cycling: "bike" })[supplied] || supplied;
  if (/(?:地铁|轨道交通)/.test(text)) return "metro";
  if (/(?:公交|巴士)/.test(text)) return "bus";
  if (/(?:打车|出租车|网约车)/.test(text)) return "taxi";
  if (/(?:开车|驾车|自驾)/.test(text)) return "drive";
  if (/(?:骑车|骑行|自行车)/.test(text)) return "bike";
  if (/(?:步行|走路)/.test(text)) return "walk";
  if (/(?:高铁|动车|火车|列车)/.test(text)) return "train";
  if (/(?:飞机|航班|机场|起飞|登机)/.test(text)) return "airport";
  if (/(?:出门|出发|前往|过去|去(?:公司|机场|车站|医院|学校|现场)|到(?:公司|机场|车站|现场))/.test(text)) return "transit";
  return "none";
}

function inferredTravelMinutes(transportation) {
  const known = { metro: 60, bus: 60, taxi: 45, drive: 45, bike: 30, walk: 20, train: 45, airport: 60, transit: 45 };
  return known[transportation] ?? (transportation === "none" ? 0 : 45);
}

function inferredPreparationMinutes(actions, kind) {
  const actionTotal = actions.reduce((total, action) => total + (ACTION_MINUTES[action] || 15), 0);
  if (actionTotal) return Math.min(180, actionTotal);
  if (kind === "flight") return 45;
  if (kind === "train") return 30;
  if (kind === "meeting") return 30;
  return 20;
}

function inferredSafetyBuffer(kind, needTravel) {
  if (kind === "flight") return 120;
  if (kind === "train") return 45;
  if (needTravel) return 30;
  if (kind === "meeting") return 15;
  return 10;
}

function roundUp(value, step = 5) {
  return Math.ceil(Math.max(0, value) / step) * step;
}

function taskKind(text, anchorKind) {
  if (anchorKind === "deadline") return "deadline";
  if (/(?:飞机|航班|机场|起飞|登机|值机)/.test(text)) return "flight";
  // Security screening is shared by rail and air travel. Explicit rail cues
  // must win over that generic word; airport/flight-specific cues stay above.
  if (/(?:高铁|动车|火车|火车站|高铁站|列车)/.test(text)) return "train";
  if (/安检/.test(text)) return "flight";
  if (/(?:会议|开会|见面|会面|面谈|拜访|聊天|约见|到公司)/.test(text)) return "meeting";
  if (/(?:跟进|回访|回复|联系)/.test(text)) return "follow_up";
  return "todo";
}

function normalizeSpec(item, anchor, fallbackType = "preparation") {
  if (!item || typeof item !== "object" || Array.isArray(item)) throw new Error("Each reminder must be an object");
  const at = normalizeAt(first(item, "at", "reminder_at", "reminderAt"), anchor.date, anchor.time);
  const suppliedOffset = integerInRange(first(item, "offset_minutes", "offsetMinutes", "reminder_offset_minutes", "reminderOffsetMinutes"), "reminder_offset_minutes");
  const offset = suppliedOffset ?? (at ? offsetFromAt(anchor.at, at) : null);
  if (offset === null) throw new Error("Each reminder requires at or offset_minutes");
  const type = String(first(item, "type", "reminder_type", "reminderType") || fallbackType);
  if (!VALID_TYPE.has(type)) throw new Error("reminder_type must be preparation, departure, or event");
  return { type, offset_minutes: offset, at: reminderAt(anchor.at, offset) };
}

function uniqueSpecs(specs) {
  const seen = new Set();
  const result = [];
  for (const spec of [...specs].sort((left, right) => right.offset_minutes - left.offset_minutes)) {
    if (seen.has(spec.offset_minutes)) continue;
    seen.add(spec.offset_minutes);
    result.push(spec);
  }
  return result.slice(0, MAX_REMINDERS);
}

function reasonFor(context) {
  if (context.task_kind === "deadline") return "需要在截止时间前启动执行并进行临近截止确认";
  const parts = [];
  if (context.pre_event_actions.length) parts.push(context.pre_event_actions.join("、"));
  else if (context.need_preparation) parts.push("提前准备");
  if (context.need_travel) {
    const label = ({ metro: "地铁通勤", bus: "公交通勤", taxi: "打车通勤", drive: "驾车通勤", bike: "骑行", walk: "步行", train: "前往车站", airport: "前往机场", transit: "通勤" })[context.transportation] || "通勤";
    parts.push(label);
  }
  if (context.safety_buffer_minutes) parts.push(`${context.safety_buffer_minutes}分钟缓冲`);
  return parts.length ? `需要${parts.join("、")}` : "固定时间事项需要在开始前推动下一步行动";
}

function policyResult({ policy, source, reason, specs, context, channel, disabled = false }) {
  const reminders = uniqueSpecs(specs);
  const primary = reminders[0] || null;
  return {
    reminder_policy: policy,
    reminder_policy_source: source,
    reminder_reason: reason || null,
    reminder_at: primary?.at || null,
    reminder_offset_minutes: primary?.offset_minutes ?? null,
    reminder_type: primary?.type || null,
    reminders,
    reminder_context: context,
    notification_channel: channel,
    notification_status: disabled ? "disabled" : reminders.length ? "pending_projection" : "not_required",
  };
}

export function mergeReminderPolicyUpdate(current = {}, update = {}) {
  if (!current || typeof current !== "object" || Array.isArray(current)) throw new Error("current reminder state must be an object");
  if (!update || typeof update !== "object" || Array.isArray(update)) throw new Error("reminder update must be an object");
  const directReminderKeys = [
    "reminder_at",
    "reminderAt",
    "reminder_offset_minutes",
    "reminderOffsetMinutes",
    "explicit_reminder_at",
    "explicitReminderAt",
    "explicit_reminder_offset_minutes",
    "explicitReminderOffsetMinutes",
    "reminder_policy",
    "reminderPolicy",
    "reminders",
  ];
  const contextKeys = [
    "raw_text",
    "need_preparation",
    "needPreparation",
    "need_travel",
    "needTravel",
    "preparation_minutes",
    "preparationMinutes",
    "travel_minutes",
    "travelMinutes",
    "safety_buffer_minutes",
    "safetyBufferMinutes",
    "transportation",
    "pre_event_actions",
    "preEventActions",
  ];
  const directReminderUpdate = directReminderKeys.some((key) => Object.hasOwn(update, key));
  const contextualSmartUpdate = contextKeys.some((key) => Object.hasOwn(update, key))
    && (update.reminder_policy === "smart" || (!update.reminder_policy && current.reminder_policy === "smart"));
  const replacesReminderSpecs = directReminderUpdate || contextualSmartUpdate;
  const sourceOverride = update.reminder_policy_source
    || (update.reminder_policy === "smart" ? "ai_inferred" : directReminderUpdate ? "user_explicit" : current.reminder_policy_source);
  return {
    ...current,
    ...(replacesReminderSpecs ? {
      reminder_at: null,
      reminder_offset_minutes: null,
      reminder_type: null,
      reminders: [],
    } : {}),
    ...update,
    ...(sourceOverride ? { reminder_policy_source: sourceOverride } : {}),
  };
}

export function resolveReminderPolicy(input = {}, { preserveReminderPolicy = false } = {}) {
  const text = [first(input, "raw_text", "rawText", "originalIntent"), first(input, "title"), first(input, "notes")]
    .filter(Boolean)
    .join("。 ");
  const anchor = reminderAnchor(input);
  const existingContext = input.reminder_context && typeof input.reminder_context === "object" && !Array.isArray(input.reminder_context)
    ? input.reminder_context
    : input.reminderContext && typeof input.reminderContext === "object" && !Array.isArray(input.reminderContext)
      ? input.reminderContext
      : {};
  const storedKind = String(existingContext.task_kind || "");
  const inferredKind = taskKind(text, anchor?.kind);
  const kind = anchor?.kind === "deadline"
    ? "deadline"
    : inferredKind !== "todo" ? inferredKind : VALID_TASK_KIND.has(storedKind) ? storedKind : inferredKind;
  const directActions = first(input, "pre_event_actions", "preEventActions");
  const storedActions = Array.isArray(existingContext.pre_event_actions) ? existingContext.pre_event_actions : [];
  const textActions = extractActions(text);
  const actions = Array.isArray(directActions)
    ? normalizedActions(input, text)
    : [...new Set([...storedActions, ...textActions].map((item) => String(item || "").trim()).filter(Boolean))].slice(0, 20);
  const suppliedTransportation = String(first(input, "transportation", "transport_mode", "transportMode") || "").trim();
  const storedTransportation = String(existingContext.transportation || "").trim();
  const textTransportation = inferTransportation({}, text);
  const suppliedMode = suppliedTransportation ? inferTransportation({ transportation: suppliedTransportation }, "") : "";
  const effectiveTransportation = suppliedMode
    || (textTransportation !== "none" && textTransportation !== "transit" ? textTransportation : "")
    || (storedTransportation && storedTransportation !== "none" ? storedTransportation : "")
    || textTransportation;
  const inferredTravel = effectiveTransportation !== "none";
  const requestedNeedTravel = explicitBoolean(input, "need_travel", "needTravel");
  const requestedNeedPreparation = explicitBoolean(input, "need_preparation", "needPreparation");
  const storedNeedTravel = typeof existingContext.need_travel === "boolean" ? existingContext.need_travel : undefined;
  const storedNeedPreparation = typeof existingContext.need_preparation === "boolean" ? existingContext.need_preparation : undefined;
  const hasExplicitTravelText = textTransportation !== "none" && textTransportation !== "transit";
  const needTravel = requestedNeedTravel ?? (hasExplicitTravelText ? true : storedNeedTravel ?? inferredTravel);
  const immediateAction = /(?:吃药|服药|喝水|签到|打卡|闹钟)/.test(text);
  const looksLikePreparation = actions.length > 0 || /(?:准备|携带|材料|设备|行李|提前到)/.test(text);
  const hasExplicitPreparationText = textActions.length > 0 || /(?:准备|携带|材料|设备|行李|提前到)/.test(text);
  const fixedTime = input.fixed_time === true || input.fixedTime === true || first(input, "scheduling_source", "schedulingSource") === "explicit_user";
  const inferredNeedPreparation = kind === "flight" || kind === "train" || kind === "meeting" || looksLikePreparation || (fixedTime && !immediateAction);
  const needPreparation = requestedNeedPreparation ?? (hasExplicitPreparationText ? true : storedNeedPreparation ?? inferredNeedPreparation);
  const travelMinutes = integerInRange(first(input, "travel_minutes", "travelMinutes") ?? existingContext.travel_minutes, "travel_minutes", 0, 1_440) ?? inferredTravelMinutes(effectiveTransportation);
  const preparationMinutes = integerInRange(first(input, "preparation_minutes", "preparationMinutes") ?? existingContext.preparation_minutes, "preparation_minutes", 0, 1_440) ?? inferredPreparationMinutes(actions, kind);
  const safetyBufferMinutes = integerInRange(first(input, "safety_buffer_minutes", "safetyBufferMinutes") ?? existingContext.safety_buffer_minutes, "safety_buffer_minutes", 0, 1_440) ?? inferredSafetyBuffer(kind, needTravel);
  const context = {
    task_kind: kind,
    anchor_kind: anchor?.kind || "none",
    need_preparation: needPreparation,
    need_travel: needTravel,
    transportation: effectiveTransportation,
    preparation_minutes: needPreparation ? preparationMinutes : 0,
    travel_minutes: needTravel ? travelMinutes : 0,
    safety_buffer_minutes: safetyBufferMinutes,
    pre_event_actions: actions,
  };
  const channel = String(first(input, "notification_channel", "notificationChannel") || "google_calendar_popup");
  if (!VALID_CHANNEL.has(channel)) throw new Error("notification_channel is invalid");
  const suppliedSource = String(first(input, "reminder_policy_source", "reminderPolicySource") || "");
  if (suppliedSource && !VALID_SOURCE.has(suppliedSource)) throw new Error("reminder_policy_source is invalid");
  const suppliedPolicy = String(first(input, "reminder_policy", "reminderPolicy") || "");
  if (suppliedPolicy && !VALID_POLICY.has(suppliedPolicy)) throw new Error("reminder_policy is invalid");
  const suppliedReason = String(first(input, "reminder_reason", "reminderReason") || "").trim() || null;
  const suppliedReminders = first(input, "reminders");

  // A task-bound preview authorizes a timing change, not a new reminder policy.
  // Projection also uses this path so repeated normalization cannot add alerts.
  if (preserveReminderPolicy) {
    const storedAt = first(input, "reminder_at", "reminderAt");
    const storedOffset = first(input, "reminder_offset_minutes", "reminderOffsetMinutes");
    const existing = suppliedPolicy === "none" ? []
      : Array.isArray(suppliedReminders) && suppliedReminders.length ? suppliedReminders
      : storedAt !== null || storedOffset !== null
        ? [{ at: storedAt, offset_minutes: storedOffset, type: first(input, "reminder_type", "reminderType") || "preparation" }]
        : [];
    const specs = anchor ? existing.map((item) => normalizeSpec(item, anchor)) : [];
    return policyResult({
      policy: suppliedPolicy || "none",
      source: suppliedSource || "system_default",
      reason: suppliedReason,
      specs,
      context,
      channel,
      disabled: suppliedPolicy === "none" && input.notification_status === "disabled",
    });
  }

  const disabledByText = /(?:不用|不要|无需|取消)(?:再)?提醒|别提醒/.test(text);
  const disabledByInput = suppliedPolicy === "none" && (!suppliedSource || suppliedSource === "user_explicit");
  if (disabledByText || disabledByInput) {
    return policyResult({ policy: "none", source: "user_explicit", reason: suppliedReason || "用户明确要求不提醒", specs: [], context, channel, disabled: true });
  }

  const explicitAt = first(input, "explicit_reminder_at", "explicitReminderAt")
    || ((!Array.isArray(suppliedReminders) || !suppliedReminders.length) ? first(input, "reminder_at", "reminderAt") : null);
  const explicitOffset = first(input, "explicit_reminder_offset_minutes", "explicitReminderOffsetMinutes")
    ?? ((!Array.isArray(suppliedReminders) || !suppliedReminders.length) ? first(input, "reminder_offset_minutes", "reminderOffsetMinutes") : null);
  const reminderClock = parseExplicitReminderClock(text);
  const textOffset = parseExplicitOffset(text);
  const explicitType = String(first(input, "reminder_type", "reminderType") || "preparation");
  if (!VALID_TYPE.has(explicitType)) throw new Error("reminder_type must be preparation, departure, or event");

  if (explicitAt !== null || explicitOffset !== null || reminderClock || textOffset !== null) {
    if (!anchor) throw new Error("An explicit reminder requires a scheduled or deadline time");
    const spec = normalizeSpec({
      type: explicitType,
      at: explicitAt || reminderClock,
      offset_minutes: explicitOffset ?? textOffset,
    }, anchor, explicitType);
    return policyResult({ policy: "custom", source: "user_explicit", reason: suppliedReason || "用户明确指定提醒时间", specs: [spec], context, channel });
  }

  if (Array.isArray(suppliedReminders) && suppliedReminders.length) {
    if (!anchor) throw new Error("Reminder overrides require a scheduled or deadline time");
    if (suppliedReminders.length > MAX_REMINDERS) throw new Error(`reminders supports at most ${MAX_REMINDERS} entries`);
    const specs = suppliedReminders.map((item) => normalizeSpec(item, anchor));
    const source = suppliedSource || (suppliedPolicy === "custom" ? "user_explicit" : "ai_inferred");
    const policy = source === "user_explicit"
      ? "custom"
      : suppliedPolicy && suppliedPolicy !== "none" ? suppliedPolicy : "smart";
    return policyResult({ policy, source, reason: suppliedReason || reasonFor(context), specs, context, channel });
  }

  if (suppliedPolicy === "custom") {
    throw new Error("A custom reminder policy requires reminder_at, reminder_offset_minutes, or reminders");
  }

  if (!anchor) {
    return policyResult({ policy: "none", source: suppliedSource || "system_default", reason: suppliedReason, specs: [], context, channel });
  }

  const wantsEarlyReminder = /(?:早点|提前|预留时间|别让我迟到)/.test(text);
  const shouldInfer = anchor.kind === "deadline" || fixedTime || wantsEarlyReminder || kind === "follow_up";
  if (!shouldInfer) {
    return policyResult({ policy: "none", source: "system_default", reason: null, specs: [], context, channel });
  }

  const specs = [];
  if (anchor.kind === "deadline") {
    const duration = integerInRange(first(input, "duration_minutes", "durationMinutes", "estimated_duration", "estimatedDuration"), "duration_minutes", 5, 720) || 30;
    specs.push(normalizeSpec({ type: "preparation", offset_minutes: roundUp(Math.max(60, duration + 30)) }, anchor));
    specs.push(normalizeSpec({ type: "event", offset_minutes: 15 }, anchor, "event"));
  } else if (immediateAction && !needTravel && !actions.length) {
    specs.push(normalizeSpec({ type: "event", offset_minutes: 0 }, anchor, "event"));
  } else {
    const departureOffset = roundUp((needTravel ? travelMinutes : 0) + safetyBufferMinutes);
    const preparationOffset = roundUp((needPreparation ? preparationMinutes : 0) + departureOffset);
    if (needPreparation) specs.push(normalizeSpec({ type: "preparation", offset_minutes: Math.max(5, preparationOffset) }, anchor));
    if (needTravel && (!needPreparation || preparationOffset - departureOffset >= 15)) {
      specs.push(normalizeSpec({ type: "departure", offset_minutes: Math.max(5, departureOffset) }, anchor, "departure"));
    }
    if (!specs.length) specs.push(normalizeSpec({ type: "event", offset_minutes: 0 }, anchor, "event"));
  }

  return policyResult({ policy: "smart", source: "ai_inferred", reason: suppliedReason || reasonFor(context), specs, context, channel });
}

export function calendarReminderOverrides(schedule = {}) {
  const reminders = Array.isArray(schedule.reminders) ? schedule.reminders : [];
  const method = schedule.notification_channel === "google_calendar_email" ? "email" : "popup";
  return uniqueSpecs(reminders
    .map((item) => ({
      type: VALID_TYPE.has(item?.type) ? item.type : "event",
      offset_minutes: integerInRange(item?.offset_minutes, "reminder_offset_minutes"),
      at: item?.at || null,
    }))
    .filter((item) => item.offset_minutes !== null))
    .map((item) => ({ method, minutes: item.offset_minutes }));
}

export function reminderActionGuidance(task, schedule = {}) {
  const reminders = Array.isArray(schedule.reminders) ? schedule.reminders : [];
  if (!reminders.length) return "";
  const context = schedule.reminder_context && typeof schedule.reminder_context === "object" ? schedule.reminder_context : {};
  const title = String(task?.title || "该事项").trim();
  const anchor = reminderAnchor(schedule);
  const when = anchor ? `${anchor.date} ${anchor.time}` : "约定时间";
  const actions = Array.isArray(context.pre_event_actions) ? context.pre_event_actions.filter(Boolean) : [];
  let instruction = actions.length ? `${actions.join("、")}后，` : "";
  if (context.task_kind === "flight") instruction += "预留前往机场、值机、安检和行李时间。";
  else if (context.task_kind === "train") instruction += "预留前往车站、取票和进站时间。";
  else if (context.need_travel) {
    const transport = ({ metro: "自己坐地铁过去", bus: "乘公交过去", taxi: "打车过去", drive: "驾车过去", bike: "骑车过去", walk: "步行过去", transit: "提前出发" })[context.transportation] || "提前出发";
    instruction += `记得${transport}，预留通勤时间。`;
  } else if (context.task_kind === "deadline") instruction += "提前开始执行，并在截止前确认完成。";
  else instruction += "按提醒开始准备。";
  return `${when} ${title}。${instruction}`;
}

export function reminderNotificationCue(schedule = {}) {
  const reminders = Array.isArray(schedule.reminders) ? schedule.reminders : [];
  if (!reminders.length) return "";
  const context = schedule.reminder_context && typeof schedule.reminder_context === "object" ? schedule.reminder_context : {};
  const actions = Array.isArray(context.pre_event_actions)
    ? context.pre_event_actions.map((item) => String(item || "").trim()).filter(Boolean).slice(0, 4)
    : [];
  const parts = actions.length ? [`${actions.join("、")}后`] : [];
  if (context.task_kind === "flight") parts.push("预留机场值机、安检和行李时间");
  else if (context.task_kind === "train") parts.push("预留前往车站和进站时间");
  else if (context.need_travel) {
    const travel = ({
      metro: "自己坐地铁过去并预留通勤时间",
      bus: "乘公交过去并预留通勤时间",
      taxi: "打车过去并预留通勤时间",
      drive: "驾车过去并预留通勤时间",
      bike: "骑车过去并预留通勤时间",
      walk: "步行过去并预留通勤时间",
      transit: "提前出发并预留通勤时间",
    })[context.transportation] || "提前出发并预留通勤时间";
    parts.push(travel);
  } else if (context.task_kind === "deadline") parts.push("提前执行并在截止前确认");
  else if (context.need_preparation) parts.push("提前开始准备");
  else parts.push("按时执行");
  return parts.join("，").slice(0, 100);
}

export function reminderProjectionFields(policy) {
  return {
    reminder_policy: policy.reminder_policy,
    reminder_policy_source: policy.reminder_policy_source,
    reminder_reason: policy.reminder_reason,
    reminder_at: policy.reminder_at,
    reminder_offset_minutes: policy.reminder_offset_minutes,
    reminder_type: policy.reminder_type,
    reminders: policy.reminders,
    reminder_context: policy.reminder_context,
    notification_channel: policy.notification_channel,
    notification_status: policy.notification_status,
  };
}

/** Evidence-based receipt. Provider configuration never proves device delivery.
 * @param {{requestId?: string|null, taskId?: string|null, taskVerified?: boolean, schedule?: any, scheduleRequested?: boolean, projection?: any, error?: any, checkedAt?: string}} options
 */
export function writeReceipt({ requestId = null, taskId = null, taskVerified = false, schedule = null, scheduleRequested = false, projection = null, error = null, checkedAt = new Date().toISOString() } = {}) {
  const p = projection?.projection || projection;
  const failed = Boolean(error || projection?.success === false || projection?.sync_required === true || p?.sync_required === true);
  const configured = !failed && p?.projected === true && Boolean(p?.verified_at) && p?.notification_status === 'projected' && p?.reminders?.length > 0;
  const disabled = p?.notification_status === 'disabled' || p?.reminder_policy === 'none' || schedule?.reminder_policy === 'none';
  const noReminder = p?.notification_status === 'not_required';
  const scheduled = Boolean(scheduleRequested || schedule?.scheduled_start || schedule?.deadline_time || p?.calendar_event_id);
  return {
    request_id: requestId, task_id: taskId,
    task_save_status: taskVerified ? 'verified' : 'unknown',
    schedule_status: schedule ? 'saved' : scheduleRequested ? 'pending' : scheduled ? 'present' : 'not_requested',
    reminder_projection_status: failed ? 'pending' : disabled ? 'disabled' : noReminder ? 'not_requested' : configured ? 'configured' : scheduled ? 'unverified' : 'not_requested',
    device_delivery_status: 'not_verified',
    readback_at: taskVerified ? checkedAt : null,
    projection_verified_at: configured ? p.verified_at : null,
    error_category: error?.code || (failed ? projection?.code || 'CALENDAR_SYNC_PENDING' : null),
    retryable: failed && error?.retryable !== false && projection?.retryable !== false && !['GOOGLE_REAUTH_REQUIRED','GOOGLE_NOT_CONNECTED','CALENDAR_SCOPE_MISSING','CALENDAR_API_DISABLED','SCHEDULER_NOT_CONFIGURED','GOOGLE_OAUTH_CONFIGURATION_ERROR'].includes(error?.code || projection?.code),
    next_step: !taskVerified ? 'reconcile_same_request' : failed ? 'recover_projection_only' : scheduled && !configured && !disabled && !noReminder ? 'verify_projection' : null,
    message: !taskVerified ? '结果待核实，请勿重复创建' : failed ? '任务已保存，提醒待恢复' : configured && !disabled ? '任务已保存，提醒配置已核实；设备到达尚未验证' : '任务已保存',
  };
}

function sameTime(expected, actual) {
  if (expected?.date) return expected.date === actual?.date;
  if (!expected?.dateTime || !actual?.dateTime) return false;
  if (/[zZ]|[+-]\d\d:\d\d$/.test(expected.dateTime)) return Date.parse(expected.dateTime) === Date.parse(actual.dateTime);
  if (expected.dateTime === actual.dateTime && expected.timeZone === actual.timeZone) return true;
  try {
    const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {timeZone:expected.timeZone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(actual.dateTime)).map(p=>[p.type,p.value]));
    return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}` === expected.dateTime;
  } catch { return false; }
}
function reminders(value) {
  return JSON.stringify((value?.overrides || []).map(x => ({method:x.method,minutes:Number(x.minutes)})).sort((a,b)=>a.method.localeCompare(b.method)||a.minutes-b.minutes));
}
export function verifyCalendarProjection(expected, actual) {
  const fail = () => { const error = new Error('Calendar projection readback did not match requested fields'); error.code = 'CALENDAR_WRITE_UNVERIFIED'; error.status = 503; throw error; };
  if (!actual || actual.id !== expected.id || actual.status === 'cancelled') fail();
  if (expected.transparency != null && (actual.transparency || 'opaque') !== expected.transparency) fail();
  for (const field of ['summary','description']) if (expected[field] != null && actual[field] !== expected[field]) fail();
  for (const field of ['start','end']) if (!sameTime(expected[field], actual[field])) fail();
  if (actual.reminders?.useDefault !== expected.reminders?.useDefault || reminders(actual.reminders) !== reminders(expected.reminders)) fail();
  for (const [key,value] of Object.entries(expected.extendedProperties?.private || {})) if (actual.extendedProperties?.private?.[key] !== value) fail();
  return true;
}

export function verifyTaskFields(current, expected) {
  const mismatch = key => { const error = new Error(`Task readback did not match requested ${key}`); error.code = 'WRITE_UNVERIFIED'; throw error; };
  for (const key of ['title','notes']) if (Object.hasOwn(expected,key) && String(current?.[key] || '').trim() !== String(expected[key] || '').trim()) mismatch(key);
  const dateKey = ['dueDate','due','date'].find(key => Object.hasOwn(expected,key));
  if (dateKey && String(current?.dueDate || current?.due || current?.date || '').slice(0,10) !== String(expected[dateKey] || '').slice(0,10)) mismatch(dateKey);
  const status = value => ['completed','done'].includes(value) ? 'completed' : value === 'cancelled' ? 'cancelled' : 'open';
  if (Object.hasOwn(expected,'status') && status(current?.status) !== status(expected.status)) mismatch('status');
  return true;
}

const GOOGLE_TOKEN_ENDPOINT = "https://oauth2.googleapis.com/token";
const refreshFlights = new Map();

export class GoogleProviderError extends Error {
  constructor(message, {
    status = 503,
    code = "GOOGLE_PROVIDER_UNAVAILABLE",
    retryable = false,
    providerLayer = "oauth",
    providerStatus = null,
    providerCode = "",
  } = {}) {
    super(message);
    this.name = "GoogleProviderError";
    this.status = status;
    this.code = code;
    this.retryable = retryable;
    this.providerLayer = providerLayer;
    this.providerStatus = providerStatus;
    this.providerCode = providerCode;
  }
}

export function providerErrorDiagnostic(error) {
  if (!(error instanceof GoogleProviderError)) return null;
  return {
    error: error.message,
    status: error.status,
    code: error.code,
    retryable: error.retryable,
    provider_layer: error.providerLayer,
    ...(Number.isInteger(error.providerStatus) ? { provider_status: error.providerStatus } : {}),
    ...(error.providerCode ? { provider_code: error.providerCode } : {}),
  };
}

export function selectRefreshToken(receivedRefreshToken, storedRefreshToken = "") {
  const received = typeof receivedRefreshToken === "string" ? receivedRefreshToken.trim() : "";
  if (received) return received;
  return typeof storedRefreshToken === "string" ? storedRefreshToken : "";
}

async function responsePayload(response) {
  const text = await response.text();
  if (!text) return null;
  try { return JSON.parse(text); } catch { return text; }
}

function providerCode(payload) {
  if (!payload || typeof payload !== "object") return "";
  return String(payload.error?.errors?.[0]?.reason || payload.error?.status || payload.error || "");
}

function retryAfterMilliseconds(response, maximum) {
  const raw = response?.headers?.get?.("retry-after");
  if (!raw) return 0;
  const seconds = Number(raw);
  if (Number.isFinite(seconds)) return Math.min(maximum, Math.max(0, seconds * 1_000));
  const date = Date.parse(raw);
  return Number.isFinite(date) ? Math.min(maximum, Math.max(0, date - Date.now())) : 0;
}

function transientNetworkError(error, providerLayer) {
  if (error instanceof GoogleProviderError) return error;
  return new GoogleProviderError(
    providerLayer === "oauth" ? "Google authorization service is temporarily unavailable" : "Google service is temporarily unavailable",
    {
      status: 503,
      code: providerLayer === "oauth" ? "GOOGLE_OAUTH_TEMPORARY_UNAVAILABLE" : "GOOGLE_PROVIDER_TEMPORARY_UNAVAILABLE",
      retryable: true,
      providerLayer,
    },
  );
}

export function classifyGoogleOAuthFailure({ status = 0, payload = null } = {}) {
  const oauthCode = providerCode(payload);
  if (oauthCode === "invalid_grant") {
    return new GoogleProviderError("Google authorization must be reconnected", {
      status: 401,
      code: "GOOGLE_REAUTH_REQUIRED",
      retryable: false,
      providerLayer: "oauth",
      providerStatus: status || null,
      providerCode: oauthCode,
    });
  }
  if (oauthCode === "invalid_client" || oauthCode === "deleted_client") {
    return new GoogleProviderError("Google OAuth client configuration is invalid", {
      status: 503,
      code: "GOOGLE_OAUTH_CONFIGURATION_ERROR",
      retryable: false,
      providerLayer: "oauth",
      providerStatus: status || null,
      providerCode: oauthCode,
    });
  }
  if (status === 429) {
    return new GoogleProviderError("Google authorization service is rate limited", {
      status: 429,
      code: "GOOGLE_OAUTH_RATE_LIMITED",
      retryable: true,
      providerLayer: "oauth",
      providerStatus: status,
      providerCode: oauthCode,
    });
  }
  if (status >= 500 || status === 0) {
    return new GoogleProviderError("Google authorization service is temporarily unavailable", {
      status: 503,
      code: "GOOGLE_OAUTH_TEMPORARY_UNAVAILABLE",
      retryable: true,
      providerLayer: "oauth",
      providerStatus: status || null,
      providerCode: oauthCode,
    });
  }
  return new GoogleProviderError("Google authorization request was rejected", {
    status: status >= 400 && status < 500 ? status : 502,
    code: "GOOGLE_OAUTH_REQUEST_REJECTED",
    retryable: false,
    providerLayer: "oauth",
    providerStatus: status || null,
    providerCode: oauthCode,
  });
}

export function classifyGoogleProviderFailure({ status = 0, payload = null, providerLayer = "tasks" } = {}) {
  const code = providerCode(payload);
  const detail = `${code} ${payload?.error?.message || ""}`;
  if (status === 401) {
    return new GoogleProviderError("Google rejected the refreshed access token", {
      status: 401,
      code: "GOOGLE_ACCESS_TOKEN_REJECTED",
      retryable: false,
      providerLayer,
      providerStatus: status,
      providerCode: code,
    });
  }
  if (status === 429 || (status === 403 && /rateLimit|quota|RESOURCE_EXHAUSTED/i.test(detail))) {
    return new GoogleProviderError("Google request rate limit reached", {
      status: 429,
      code: "GOOGLE_RATE_LIMITED",
      retryable: true,
      providerLayer,
      providerStatus: status,
      providerCode: code,
    });
  }
  if (status >= 500 || status === 0) {
    return new GoogleProviderError("Google service is temporarily unavailable", {
      status: 503,
      code: "GOOGLE_PROVIDER_TEMPORARY_UNAVAILABLE",
      retryable: true,
      providerLayer,
      providerStatus: status || null,
      providerCode: code,
    });
  }
  if (status === 403 && /disabled|not been used|accessnotconfigured|SERVICE_DISABLED/i.test(detail)) {
    return new GoogleProviderError(`Google ${providerLayer} API is disabled`, {
      status: 503,
      code: providerLayer === "calendar" ? "CALENDAR_API_DISABLED" : "TASKS_API_DISABLED",
      retryable: false,
      providerLayer,
      providerStatus: status,
      providerCode: code,
    });
  }
  if (status === 403 && /insufficient|permission|scope|ACCESS_TOKEN_SCOPE_INSUFFICIENT/i.test(detail)) {
    return new GoogleProviderError(`Google ${providerLayer} permission is missing`, {
      status: 403,
      code: providerLayer === "calendar" ? "CALENDAR_SCOPE_MISSING" : "SCOPE_MISSING",
      retryable: false,
      providerLayer,
      providerStatus: status,
      providerCode: code,
    });
  }
  if (status === 404) {
    return new GoogleProviderError("Google object was not found", {
      status: 404,
      code: "GOOGLE_OBJECT_NOT_FOUND",
      retryable: false,
      providerLayer,
      providerStatus: status,
      providerCode: code,
    });
  }
  if (status === 409) {
    return new GoogleProviderError("Google object already exists", {
      status: 409,
      code: "GOOGLE_OBJECT_EXISTS",
      retryable: false,
      providerLayer,
      providerStatus: status,
      providerCode: code,
    });
  }
  if (status === 412) {
    return new GoogleProviderError("Google object changed after it was read", {
      status: 409,
      code: "GOOGLE_OBJECT_CHANGED",
      retryable: false,
      providerLayer,
      providerStatus: status,
      providerCode: code,
    });
  }
  return new GoogleProviderError("Google request failed", {
    status: status >= 400 ? status : 502,
    code: providerLayer === "calendar" ? "GOOGLE_CALENDAR_ERROR" : "GOOGLE_TASKS_ERROR",
    retryable: false,
    providerLayer,
    providerStatus: status || null,
    providerCode: code,
  });
}

async function boundedRetry(work, {
  attempts,
  sleep,
  random,
  baseDelayMs,
  maxDelayMs,
}) {
  let lastError;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try { return await work(attempt); }
    catch (error) {
      lastError = error;
      if (!(error instanceof GoogleProviderError) || !error.retryable || attempt >= attempts) throw error;
      const exponential = Math.min(maxDelayMs, baseDelayMs * (2 ** (attempt - 1)));
      const jitter = Math.floor(Math.max(0, random()) * Math.min(baseDelayMs, maxDelayMs));
      await sleep(Math.min(maxDelayMs, Math.max(error.retryAfterMs || 0, exponential + jitter)));
    }
  }
  throw lastError;
}

async function refreshWithoutSingleflight({
  clientId,
  clientSecret,
  refreshToken,
  fetchImpl,
  sleep,
  random,
  attempts,
  timeoutMs,
  baseDelayMs,
  maxDelayMs,
}) {
  if (!clientId || !clientSecret) {
    throw new GoogleProviderError("Google OAuth client configuration is incomplete", {
      status: 503,
      code: "GOOGLE_OAUTH_CONFIGURATION_ERROR",
      retryable: false,
      providerLayer: "oauth",
    });
  }
  if (!refreshToken) {
    throw new GoogleProviderError("Google Tasks is not connected", {
      status: 428,
      code: "GOOGLE_NOT_CONNECTED",
      retryable: false,
      providerLayer: "credential_store",
    });
  }
  return boundedRetry(async () => {
    let response;
    try {
      response = await fetchImpl(GOOGLE_TOKEN_ENDPOINT, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          client_id: clientId,
          client_secret: clientSecret,
          refresh_token: refreshToken,
          grant_type: "refresh_token",
        }),
        signal: AbortSignal.timeout(timeoutMs),
      });
    } catch (error) {
      throw transientNetworkError(error, "oauth");
    }
    let payload;
    try { payload = await responsePayload(response); }
    catch (error) { throw transientNetworkError(error, "oauth"); }
    if (!response.ok) {
      const error = classifyGoogleOAuthFailure({ status: response.status, payload });
      error.retryAfterMs = retryAfterMilliseconds(response, maxDelayMs);
      throw error;
    }
    if (!payload?.access_token) {
      throw new GoogleProviderError("Google authorization response was incomplete", {
        status: 502,
        code: "GOOGLE_OAUTH_INVALID_RESPONSE",
        retryable: false,
        providerLayer: "oauth",
        providerStatus: response.status,
      });
    }
    return {
      accessToken: String(payload.access_token),
      refreshToken: selectRefreshToken(payload.refresh_token, refreshToken),
      expiresIn: Number(payload.expires_in) || null,
      scope: typeof payload.scope === "string" ? payload.scope : "",
      tokenType: typeof payload.token_type === "string" ? payload.token_type : "Bearer",
    };
  }, { attempts, sleep, random, baseDelayMs, maxDelayMs });
}

/** @param {{ownerId: string, clientId: string, clientSecret: string, refreshToken: string, fetchImpl?: typeof fetch, sleep?: (milliseconds: number) => Promise<void>, random?: () => number, attempts?: number, timeoutMs?: number, baseDelayMs?: number, maxDelayMs?: number}} options */
export function refreshGoogleAccessToken({
  ownerId,
  clientId,
  clientSecret,
  refreshToken,
  fetchImpl = globalThis.fetch,
  sleep = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds)),
  random = Math.random,
  attempts = 3,
  timeoutMs = 10_000,
  baseDelayMs = 500,
  maxDelayMs = 2_000,
} = {}) {
  const ownerKey = String(ownerId || "");
  const options = { clientId, clientSecret, refreshToken, fetchImpl, sleep, random, attempts: Math.max(1, Math.min(3, attempts)), timeoutMs, baseDelayMs, maxDelayMs };
  const current = refreshFlights.get(ownerKey);
  if (current) {
    if (current.refreshToken === refreshToken) return current.promise;
    return current.promise.catch(() => undefined).then(() => refreshGoogleAccessToken({ ownerId, ...options }));
  }
  const promise = refreshWithoutSingleflight(options);
  refreshFlights.set(ownerKey, { refreshToken, promise });
  promise.finally(() => {
    if (refreshFlights.get(ownerKey)?.promise === promise) refreshFlights.delete(ownerKey);
  }).catch(() => undefined);
  return promise;
}

/** @param {{accessToken: string, url: string, init?: RequestInit, providerLayer?: string, fetchImpl?: typeof fetch, sleep?: (milliseconds: number) => Promise<void>, random?: () => number, readAttempts?: number, timeoutMs?: number, baseDelayMs?: number, maxDelayMs?: number}} options */
export async function googleJsonRequest({
  accessToken,
  url,
  init = {},
  providerLayer = "tasks",
  fetchImpl = globalThis.fetch,
  sleep = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds)),
  random = Math.random,
  readAttempts = 3,
  timeoutMs = 10_000,
  baseDelayMs = 500,
  maxDelayMs = 2_000,
} = {}) {
  const method = String(init.method || "GET").toUpperCase();
  const safeRead = method === "GET" || method === "HEAD";
  const attempts = safeRead ? Math.max(1, Math.min(3, readAttempts)) : 1;
  return boundedRetry(async () => {
    let response;
    try {
      response = await fetchImpl(url, {
        ...init,
        headers: {
          Authorization: `Bearer ${accessToken}`,
          "Content-Type": "application/json",
          ...(init.headers || {}),
        },
        signal: init.signal || AbortSignal.timeout(timeoutMs),
      });
    } catch (error) {
      throw transientNetworkError(error, providerLayer);
    }
    let payload;
    try { payload = await responsePayload(response); }
    catch (error) { throw transientNetworkError(error, providerLayer); }
    if (!response.ok) {
      const error = classifyGoogleProviderFailure({ status: response.status, payload, providerLayer });
      error.retryAfterMs = retryAfterMilliseconds(response, maxDelayMs);
      throw error;
    }
    return payload;
  }, { attempts, sleep, random, baseDelayMs, maxDelayMs });
}

const GOOGLE_USERINFO_ENDPOINT = "https://openidconnect.googleapis.com/v1/userinfo";
const GOOGLE_CALENDAR_PROBE = "https://www.googleapis.com/calendar/v3/users/me/calendarList?maxResults=1";

export async function googleSubjectForAccessToken(accessToken, { fetchImpl = globalThis.fetch, timeoutMs = 10_000 } = {}) {
  if (!accessToken) throw new GoogleProviderError("Google account identity is unavailable", {
    status: 409, code: "GOOGLE_ACCOUNT_UNVERIFIED", providerLayer: "identity",
  });
  let response;
  try {
    response = await fetchImpl(GOOGLE_USERINFO_ENDPOINT, {
      headers: { Authorization: `Bearer ${accessToken}` }, signal: AbortSignal.timeout(timeoutMs),
    });
  } catch (error) { throw transientNetworkError(error, "identity"); }
  let payload;
  try { payload = await responsePayload(response); }
  catch (error) { throw transientNetworkError(error, "identity"); }
  if (!response.ok || typeof payload?.sub !== "string" || !payload.sub) {
    throw new GoogleProviderError("Google account identity could not be verified", {
      status: response.status === 403 ? 403 : response.status === 429 || response.status >= 500 ? 503 : 409,
      code: response.status === 403 ? "GOOGLE_IDENTITY_SCOPE_MISSING" : "GOOGLE_ACCOUNT_UNVERIFIED",
      retryable: response.status === 429 || response.status >= 500,
      providerLayer: "identity", providerStatus: response.status,
    });
  }
  return payload.sub;
}

export function assertSameGoogleSubject(currentSubject, candidateSubject) {
  if (!currentSubject || !candidateSubject) throw new GoogleProviderError("Original Google account could not be verified", {
    status: 409, code: "GOOGLE_ACCOUNT_UNVERIFIED", providerLayer: "identity",
  });
  if (currentSubject !== candidateSubject) throw new GoogleProviderError("Different Google account selected", {
    status: 409, code: "GOOGLE_ACCOUNT_MISMATCH", providerLayer: "identity",
  });
}

export function assertAuthenticatedGoogleIdentity(user, candidateSubject) {
  const identities = Array.isArray(user?.identities) ? user.identities : [];
  const googleSubjects = identities
    .filter((identity) => identity?.provider === "google")
    .map((identity) => identity?.provider_id)
    .filter((subject) => typeof subject === "string" && subject.length > 0);
  if (!googleSubjects.length) throw new GoogleProviderError("Authenticated Google identity is unavailable", {
    status: 409, code: "GOOGLE_LOGIN_IDENTITY_UNAVAILABLE", providerLayer: "identity",
  });
  if (!googleSubjects.includes(candidateSubject)) throw new GoogleProviderError("Google Tasks account differs from the signed-in Google account", {
    status: 409, code: "GOOGLE_LOGIN_ACCOUNT_MISMATCH", providerLayer: "identity",
  });
}

export async function proveLegacyTaskList(accessToken, storedTaskListId, { fetchImpl = globalThis.fetch } = {}) {
  if (!accessToken || !storedTaskListId) throw new GoogleProviderError("Original Google task list cannot be verified", {
    status: 409, code: "GOOGLE_LEGACY_ACCOUNT_UNVERIFIED", providerLayer: "identity",
  });
  let taskList;
  try {
    taskList = await googleJsonRequest({
      accessToken,
      url: `https://tasks.googleapis.com/tasks/v1/users/@me/lists/${encodeURIComponent(storedTaskListId)}`,
      providerLayer: "tasks", fetchImpl,
    });
  } catch {
    throw new GoogleProviderError("Original Google task list cannot be verified", {
      status: 409, code: "GOOGLE_LEGACY_ACCOUNT_UNVERIFIED", providerLayer: "identity",
    });
  }
  if (taskList?.id !== storedTaskListId) throw new GoogleProviderError("Original Google task list cannot be verified", {
    status: 409, code: "GOOGLE_LEGACY_ACCOUNT_UNVERIFIED", providerLayer: "identity",
  });
  return true;
}

export async function probeGoogleCapabilities(accessToken, {
  fetchImpl = globalThis.fetch, sleep = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds)),
} = {}) {
  const probe = async (url, providerLayer) => {
    try {
      await googleJsonRequest({ accessToken, url, providerLayer, fetchImpl, sleep, readAttempts: 1 });
      return "ok";
    } catch (error) {
      if (error?.code === "CALENDAR_SCOPE_MISSING" || error?.code === "SCOPE_MISSING") return "scope_missing";
      return "unavailable";
    }
  };
  const [tasks, calendar] = await Promise.all([
    probe("https://tasks.googleapis.com/tasks/v1/users/@me/lists?maxResults=1", "tasks"),
    probe(GOOGLE_CALENDAR_PROBE, "calendar"),
  ]);
  return { tasks, calendar };
}

// `rpc` is the existing service-role PostgREST caller. The lease and cache are
// database-backed so separate Edge isolates observe the same refresh result.
/** @param {{ownerId: string, encryptionKey: string, rpc: (name: string, body: Record<string, unknown>) => Promise<any>, clientId: string, clientSecret: string, fetchImpl?: typeof fetch, sleep?: (milliseconds: number) => Promise<void>, now?: () => number, maxWaitMs?: number}} options */
export async function coordinatedGoogleAccess({
  ownerId, encryptionKey, rpc, clientId, clientSecret,
  fetchImpl = globalThis.fetch,
  sleep = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds)),
  now = Date.now, maxWaitMs = 50_000,
} = {}) {
  if (!ownerId || !encryptionKey || typeof rpc !== "function") throw new GoogleProviderError("Google credential store is unavailable", {
    status: 503, code: "CREDENTIAL_STORE_ERROR", providerLayer: "credential_store", retryable: true,
  });
  const started = now();
  while (now() - started < maxWaitMs) {
    const leaseId = crypto.randomUUID();
    const claim = (await rpc("claim_google_auth_refresh", {
      target_owner: ownerId, new_lease_id: leaseId, encryption_key: encryptionKey,
    }))?.[0];
    if (claim?.outcome === "missing") throw new GoogleProviderError("Google Tasks is not connected", {
      status: 428, code: "GOOGLE_NOT_CONNECTED", providerLayer: "credential_store",
    });
    if (claim?.outcome === "cached" && claim.access_token) {
      let subject = claim.google_subject || null;
      if (!subject) {
        try {
          const verified = await googleSubjectForAccessToken(claim.access_token, { fetchImpl });
          const bound = await rpc("bind_google_auth_subject", {
            target_owner: ownerId, expected_access_token: claim.access_token,
            verified_google_subject: verified, encryption_key: encryptionKey,
          });
          if (!bound) continue; // Reconnect or refresh changed the cached token.
          subject = verified;
        } catch (error) {
          if (error instanceof GoogleProviderError && !error.retryable) {
            // A legacy token without identity scope can still serve Tasks, but
            // callers requiring account-bound recovery must reject null.
          } else throw error;
        }
      }
      return { accessToken: claim.access_token, taskListId: claim.tasklist_id, googleSubject: subject,
        capabilities: { tasks: claim.tasks_health || "unknown", calendar: claim.calendar_health || "unknown",
          checkedAt: claim.capability_checked_at || null }, lastSuccessAt: claim.last_success_at || null,
        lastErrorCode: claim.last_error_code || null };
    }
    if (claim?.outcome === "busy") {
      await sleep(Math.min(1_000, Math.max(100, Number(claim.retry_after_ms) || 250)));
      continue;
    }
    if (claim?.outcome !== "claimed" || !claim.refresh_token) throw new GoogleProviderError("Google refresh lease could not be acquired", {
      status: 503, code: "GOOGLE_REFRESH_COORDINATION_ERROR", providerLayer: "credential_store", retryable: true,
    });
    try {
      const token = await refreshGoogleAccessToken({
        ownerId, clientId, clientSecret, refreshToken: claim.refresh_token, fetchImpl, sleep,
      });
      let verifiedSubject = null;
      if (!claim.google_subject) {
        // Legacy rows are backfilled only from their own working credential.
        try { verifiedSubject = await googleSubjectForAccessToken(token.accessToken, { fetchImpl }); }
        catch { /* Tasks can still work; reconnect remains blocked until identity is proven. */ }
      }
      const saved = await rpc("finish_google_auth_refresh", {
        target_owner: ownerId, held_lease_id: leaseId,
        old_refresh_token: claim.refresh_token,
        new_refresh_token: token.refreshToken === claim.refresh_token ? "" : token.refreshToken,
        new_access_token: token.accessToken, expires_in_seconds: token.expiresIn || 3600,
        verified_google_subject: verifiedSubject, encryption_key: encryptionKey,
      });
      if (saved === true) return {
        accessToken: token.accessToken, taskListId: claim.tasklist_id,
        googleSubject: claim.google_subject || verifiedSubject,
        capabilities: { tasks: claim.tasks_health || "unknown", calendar: claim.calendar_health || "unknown",
          checkedAt: claim.capability_checked_at || null },
        lastSuccessAt: new Date().toISOString(), lastErrorCode: null,
      };
      // A reconnect or another owner of the lease won. Read the current state.
      await rpc("fail_google_auth_refresh", {
        target_owner: ownerId, held_lease_id: leaseId,
        safe_error_code: "GOOGLE_REFRESH_STATE_CHANGED",
      });
    } catch (error) {
      try { await rpc("fail_google_auth_refresh", {
        target_owner: ownerId, held_lease_id: leaseId,
        safe_error_code: error?.code || "GOOGLE_REFRESH_ERROR",
      }); } catch { /* Preserve the original provider error. */ }
      throw error;
    }
  }
  throw new GoogleProviderError("Google authorization is still recovering", {
    status: 503, code: "GOOGLE_REFRESH_IN_PROGRESS", providerLayer: "credential_store", retryable: true,
  });
}

export const GOOGLE_TASKS_SCOPE = "https://www.googleapis.com/auth/tasks";
export const DEFAULT_TASK_LIST_TITLE = "Personal OS";

const ORIGINAL_INTENT_PREFIX = "原始意图：";
const TASK_CANCELLED_MARKER = "[Personal OS status: cancelled]";
const TASK_STATUS = new Set(["open", "completed", "cancelled"]);

export function validDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(value || ""))) return false;
  const parsed = new Date(`${value}T00:00:00Z`);
  return !Number.isNaN(parsed.valueOf()) && parsed.toISOString().slice(0, 10) === value;
}

export function dateToGoogleDue(date) {
  if (!validDate(date)) throw new Error("dueDate must be YYYY-MM-DD");
  return `${date}T00:00:00.000Z`;
}

export function googleDueToDate(due) {
  return typeof due === "string" && /^\d{4}-\d{2}-\d{2}T/.test(due) ? due.slice(0, 10) : null;
}

export function splitTaskNotes(value) {
  const lines = String(value || "").split("\n");
  const requestLine = lines.find(line => /^\[Personal OS request: [a-zA-Z0-9:_-]+\]$/.test(line.trim()));
  const recurrenceLine = lines.find(line => /^\[Personal OS recurrence: [a-zA-Z0-9:_-]+\]$/.test(line.trim()));
  const correlation = {
    ...(requestLine ? {request_id: requestLine.trim().slice(22,-1)} : {}),
    ...(recurrenceLine ? {recurrence_key: recurrenceLine.trim().slice(25,-1)} : {}),
  };
  for (let i=lines.length-1;i>=0;i--) if (lines[i]===requestLine || lines[i]===recurrenceLine) lines.splice(i,1);
  const cancelled = lines.some((line) => line.trim() === TASK_CANCELLED_MARKER);
  for (let index = lines.length - 1; index >= 0; index -= 1) {
    if (lines[index].trim() === TASK_CANCELLED_MARKER) lines.splice(index, 1);
  }
  const index = lines.findLastIndex((line) => line.startsWith(ORIGINAL_INTENT_PREFIX));
  if (index < 0) return { ...correlation, notes: lines.join("\n").trim(), originalIntent: "", ...(cancelled ? { cancelled: true } : {}) };
  const originalIntent = lines[index].slice(ORIGINAL_INTENT_PREFIX.length).trim();
  lines.splice(index, 1);
  return { ...correlation, notes: lines.join("\n").trim(), originalIntent, ...(cancelled ? { cancelled: true } : {}) };
}

export function markTaskCancelledNotes(notes, originalIntent = "") {
  const composed = composeTaskNotes(notes, originalIntent);
  const withoutMarker = composed.split("\n").filter((line) => line.trim() !== TASK_CANCELLED_MARKER).join("\n").trim();
  return `${withoutMarker}${withoutMarker ? "\n\n" : ""}${TASK_CANCELLED_MARKER}`;
}

export function clearTaskCancelledNotes(notes) {
  return String(notes || "").split("\n").filter((line) => line.trim() !== TASK_CANCELLED_MARKER).join("\n").trim();
}

export function composeTaskNotes(notes, originalIntent) {
  const cleanNotes = String(notes || "").trim();
  const cleanIntent = String(originalIntent || "").replace(/\s+/g, " ").trim();
  const combined = cleanIntent
    ? `${cleanNotes}${cleanNotes ? "\n\n" : ""}${ORIGINAL_INTENT_PREFIX}${cleanIntent}`
    : cleanNotes;
  return combined.slice(0, 8192);
}

export function toTaskModel(task, taskListId = "") {
  const parsedNotes = splitTaskNotes(task.notes);
  const cancelled = task.status === "completed" && parsedNotes.cancelled;
  const completed = task.status === "completed" && !cancelled;
  const dueDate = googleDueToDate(task.due);
  return {
    id: task.id,
    externalId: task.id,
    provider: "google_tasks",
    taskListId,
    title: task.title || "",
    notes: parsedNotes.notes,
    status: cancelled ? "cancelled" : completed ? "completed" : "open",
    dueDate,
    createdAt: null,
    updatedAt: task.updated || null,
    completedAt: completed ? task.completed || null : null,
    cancelledAt: cancelled ? task.completed || task.updated || null : null,
    source: "google_tasks",
    sourceConversationId: null,
    projectId: null,
    customerId: null,
    originalIntent: parsedNotes.originalIntent,
    priority: "medium",
    parent_task_id: task.parent || null,
    metadata: { ...(parsedNotes.request_id ? { request_id: parsedNotes.request_id } : {}), ...(parsedNotes.recurrence_key ? { recurrence_key: parsedNotes.recurrence_key } : {}) },
    date: dueDate || "",
    time: "",
    category: "Google Tasks",
    duration: 0,
    done: completed,
    completed_at: task.completed || null,
    created_at: null,
    updated_at: task.updated || null,
    carried_from_date: null,
  };
}

export const toPublicTask = toTaskModel;

export function preserveTaskCorrelation(payload, task) {
  if (!Object.hasOwn(payload, "notes")) return payload;
  const request = task?.requestCorrelationId || task?.metadata?.request_id;
  const recurrence = task?.metadata?.recurrence_key;
  const markers = [request && /^[a-zA-Z0-9:_-]+$/.test(request) ? `[Personal OS request: ${request}]` : null,
    recurrence && /^[a-zA-Z0-9:_-]+$/.test(recurrence) ? `[Personal OS recurrence: ${recurrence}]` : null].filter(Boolean);
  if (!markers.length) return payload;
  const suffix = "\n\n" + markers.join("\n");
  payload.notes = String(payload.notes || "").slice(0, 8192 - suffix.length) + suffix;
  return payload;
}

export function createGoogleTaskPayload(input) {
  const title = typeof input?.title === "string" ? input.title.trim() : "";
  if (!title || title.length > 200) throw new Error("title must contain 1-200 characters");
  const dueDate = input.dueDate || input.due || input.date || "";
  const payload = {
    title,
    notes: composeTaskNotes(input.notes, input.originalIntent),
  };
  if (dueDate) payload.due = dateToGoogleDue(dueDate);
  if (input.status === "completed" || input.status === "done") payload.status = "completed";
  return preserveTaskCorrelation(payload, input);
}

export function updateGoogleTaskPayload(changes) {
  const payload = {};
  if (Object.hasOwn(changes, "title")) {
    const title = typeof changes.title === "string" ? changes.title.trim() : "";
    if (!title || title.length > 200) throw new Error("title must contain 1-200 characters");
    payload.title = title;
  }
  if (Object.hasOwn(changes, "notes") || Object.hasOwn(changes, "originalIntent")) {
    payload.notes = composeTaskNotes(changes.notes, changes.originalIntent);
  }
  const hasDueDate = ["dueDate", "due", "date"].some((key) => Object.hasOwn(changes, key));
  if (hasDueDate) {
    const dueDate = changes.dueDate ?? changes.due ?? changes.date;
    payload.due = dueDate ? dateToGoogleDue(dueDate) : null;
  }
  if (Object.hasOwn(changes, "status")) {
    if (!TASK_STATUS.has(changes.status) && changes.status !== "done") throw new Error("status must be open or completed");
    const completed = changes.status === "completed" || changes.status === "done";
    payload.status = completed ? "completed" : "needsAction";
    if (!completed) payload.completed = null;
  }
  return preserveTaskCorrelation(payload, changes);
}

export function normalizeTaskTitle(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/(?:今天|明天|后天|本周|这周|下周末|下周[一二三四五六日天]?|周[一二三四五六日天]|星期[一二三四五六日天])/g, "")
    .replace(/(?:提醒我|记得|麻烦|请|一下|那个|这个|的)/g, "")
    .replace(/[\s\p{P}\p{S}]/gu, "");
}

function characterBigrams(value) {
  if (value.length < 2) return new Set(value ? [value] : []);
  return new Set(Array.from({ length: value.length - 1 }, (_, index) => value.slice(index, index + 2)));
}

export function taskTitleSimilarity(left, right) {
  const normalizedLeft = normalizeTaskTitle(left);
  const normalizedRight = normalizeTaskTitle(right);
  if (!normalizedLeft || !normalizedRight) return 0;
  if (normalizedLeft === normalizedRight) return 1;
  if (normalizedLeft.includes(normalizedRight) || normalizedRight.includes(normalizedLeft)) {
    return Math.min(normalizedLeft.length, normalizedRight.length) / Math.max(normalizedLeft.length, normalizedRight.length);
  }
  const leftBigrams = characterBigrams(normalizedLeft);
  const rightBigrams = characterBigrams(normalizedRight);
  const overlap = [...leftBigrams].filter((part) => rightBigrams.has(part)).length;
  return (2 * overlap) / (leftBigrams.size + rightBigrams.size || 1);
}

export function findDuplicateTask(input, tasks, threshold = 0.82) {
  const dueDate = input.dueDate || input.due || input.date || "";
  return tasks
    .filter((task) => task.status === "open" || task.status === "needsAction")
    .map((task) => ({ task, score: taskTitleSimilarity(input.title, task.title) }))
    .filter(({ task, score }) => score >= threshold && (!dueDate || !task.dueDate || task.dueDate === dueDate))
    .sort((left, right) => right.score - left.score)[0]?.task || null;
}

export function filterTaskModels(tasks, filter = "all", date = "") {
  const open = tasks.filter((task) => task.status === "open");
  if (filter === "completed") return tasks.filter((task) => task.status === "completed");
  if (filter === "today") return open.filter((task) => task.dueDate === date);
  if (filter === "overdue") return open.filter((task) => task.dueDate && task.dueDate < date);
  if (filter === "upcoming") return open.filter((task) => !task.dueDate || task.dueDate > date);
  if (filter === "open") return open;
  return tasks;
}

export function chooseTaskList(taskLists, preferredTitle = DEFAULT_TASK_LIST_TITLE) {
  const normalized = preferredTitle.trim().toLocaleLowerCase();
  return taskLists.find((list) => String(list.title || "").trim().toLocaleLowerCase() === normalized) || null;
}

function namedKey(raw, name = "default") {
  const value = typeof raw === "string" ? raw.trim() : "";
  if (!value) return "";
  if (value.startsWith("sb_")) return value;
  try {
    const keys = JSON.parse(value);
    return typeof keys?.[name] === "string" ? keys[name].trim() : "";
  } catch {
    return "";
  }
}

export function resolveServiceApiKey({ secretKeys = "", serviceRoleKey = "", preferNew = false } = {}) {
  const current = namedKey(secretKeys);
  const legacy = String(serviceRoleKey || "").trim();
  return preferNew ? current || legacy : legacy || current;
}

export function resolvePublishableApiKey({ publishableKeys = "", anonKey = "", preferNew = false } = {}) {
  const current = namedKey(publishableKeys);
  const legacy = String(anonKey || "").trim();
  return preferNew ? current || legacy : legacy || current;
}

export function serviceApiHeaders(apiKey) {
  const key = String(apiKey || "").trim();
  return Object.fromEntries([
    ["apikey", key],
    ...(key && !key.startsWith("sb_secret_") ? [["Authorization", `Bearer ${key}`]] : []),
  ]);
}

import { validateTaskRelationship } from "./task-graph-core.js";
import { executeTaskResolution } from "./task-resolution-executor.js";
import { extractIntentProfile, resolveTaskIntent } from "./task-resolution-engine.js";

const CLOSED_GOAL_STATUSES = new Set(["completed", "dropped", "archived"]);
const COMPLETE_TASK_STATUSES = new Set(["completed", "done"]);
const SYMMETRIC_RELATIONSHIPS = new Set([
  "RELATED_TO",
  "POTENTIAL_RELATION",
  "CONFLICTS_WITH",
  "SHARES_RESOURCE",
]);

function clean(value, maxLength = 20_000) {
  return typeof value === "string" ? value.trim().slice(0, maxLength) : "";
}

function taskId(task) {
  return clean(task?.task_id || task?.google_task_id || task?.id || task?.externalId, 1_024);
}

function statusOf(task) {
  return clean(task?.status, 40).toLowerCase() || (task?.done ? "completed" : "open");
}

function timestampOf(task) {
  for (const value of [task?.completedAt, task?.completed_at, task?.updatedAt, task?.updated_at, task?.createdAt, task?.created_at]) {
    const parsed = Date.parse(String(value || ""));
    if (Number.isFinite(parsed)) return parsed;
  }
  return 0;
}

function uniqueStrings(values = []) {
  return [...new Set(values.map((value) => clean(String(value), 1_024)).filter(Boolean))];
}

function mergedResourceAccess(left, right) {
  const values = new Set([left, right].filter(Boolean));
  if (values.has("read_write") || (values.has("read") && values.has("write"))) return "read_write";
  return values.has("write") ? "write" : "read";
}

function canonicalRelationship(item) {
  const relationship = {
    ...item,
    relationship_type: clean(item?.relationship_type || item?.type, 80).toUpperCase(),
    from_task_id: clean(item?.from_task_id || item?.from, 1_024),
    to_task_id: clean(item?.to_task_id || item?.to, 1_024),
  };
  if (SYMMETRIC_RELATIONSHIPS.has(relationship.relationship_type)
    && relationship.from_task_id.localeCompare(relationship.to_task_id) > 0) {
    [relationship.from_task_id, relationship.to_task_id] = [relationship.to_task_id, relationship.from_task_id];
  }
  return relationship;
}

function resolutionAuditPayload(ownerId, audit, plan, options) {
  return {
    owner_id: ownerId,
    intake_audit_id: options.intakeAuditId || null,
    idempotency_key: options.resolutionIdempotencyKey || null,
    original_intent: clean(audit.original_intent, 10_000),
    normalized_intent: audit.normalized_intent || {},
    decision: audit.decision,
    confidence: audit.confidence,
    automatic_action: clean(plan.automatic_action, 80)
      || plan.operations.map((item) => item.type).join("+").toUpperCase().slice(0, 80)
      || "CREATE",
    existing_task_id: audit.existing_task_id || null,
    candidate_snapshot: audit.candidate_snapshot || [],
    related_object_ids: audit.related_object_ids || {},
    reason: clean(audit.reason, 4_000),
    status: "processing",
  };
}

/**
 * Keep retrieval bounded before semantic scoring. Open Tasks are always eligible;
 * only recently completed Tasks are retained as historical candidates.
 */
export function selectTaskCandidateWindow(tasks = [], options = {}) {
  const now = options.now instanceof Date ? options.now : new Date(options.now || Date.now());
  const completedSince = now.valueOf() - Math.max(1, Number(options.recentCompletedDays || 90)) * 86_400_000;
  const openLimit = Math.max(1, Math.min(5_000, Number(options.openLimit || 400)));
  const completedLimit = Math.max(0, Math.min(500, Number(options.completedLimit ?? 100)));
  const seen = new Set();
  const eligible = tasks.filter((task) => {
    const id = taskId(task);
    if (!id || seen.has(id)) return false;
    seen.add(id);
    const completed = COMPLETE_TASK_STATUSES.has(statusOf(task));
    return !completed || timestampOf(task) >= completedSince;
  });
  const open = eligible.filter((task) => !COMPLETE_TASK_STATUSES.has(statusOf(task)))
    .sort((left, right) => timestampOf(right) - timestampOf(left))
    .slice(0, openLimit);
  const completed = eligible.filter((task) => COMPLETE_TASK_STATUSES.has(statusOf(task)))
    .sort((left, right) => timestampOf(right) - timestampOf(left))
    .slice(0, completedLimit);
  return [...open, ...completed];
}

/** Join durable semantic metadata to freshly read provider truth. */
export function enrichTaskCandidates(tasks = [], profiles = []) {
  const profileByTask = new Map(profiles.map((profile) => [String(profile.google_task_id), profile]));
  return tasks.map((task) => {
    const profile = profileByTask.get(taskId(task));
    if (!profile) return task;
    const inferred = extractIntentProfile(task);
    return {
      ...task,
      canonical_task_id: profile.canonical_task_id || taskId(task),
      normalized_text: profile.normalized_title || inferred.normalized_text,
      semantic_key: profile.semantic_key || inferred.semantic_key,
      action: profile.action || inferred.action,
      entities: profile.entities?.length ? profile.entities : inferred.entities,
      topics: profile.topics?.length ? profile.topics : inferred.topics,
      months: inferred.months,
      resources: profile.resources?.length ? profile.resources : inferred.resources,
      read_resources: profile.read_resources?.length ? profile.read_resources : inferred.read_resources,
      write_resources: profile.write_resources?.length ? profile.write_resources : inferred.write_resources,
      resource_fields: profile.resource_fields?.length ? profile.resource_fields : inferred.resource_fields,
      goal_plan_id: profile.goal_plan_id || null,
      project_id: profile.project_id || null,
      due: task?.dueDate || task?.due || task?.date || null,
      additive: false,
      explicit_merge: false,
      explicit_update: false,
      dependency_cue: false,
      parent_child_cue: false,
    };
  });
}

export function selectGoalCandidateWindow(goals = [], limit = 100) {
  return goals
    .filter((goal) => goal?.id && !CLOSED_GOAL_STATUSES.has(clean(goal.status, 40).toLowerCase()))
    .sort((left, right) => String(right.updated_at || "").localeCompare(String(left.updated_at || "")))
    .slice(0, Math.max(1, Math.min(200, Number(limit) || 100)));
}

export function buildTaskResolutionContext(tasks = [], profiles = [], goals = [], options = {}) {
  return {
    tasks: enrichTaskCandidates(selectTaskCandidateWindow(tasks, options), profiles),
    goals: selectGoalCandidateWindow(goals, options.goalLimit || 100),
    candidate_limit: Math.max(1, Math.min(50, Number(options.candidateLimit || 20))),
  };
}

export async function loadTaskResolutionContext(configuration = {}) {
  const {
  serviceRest,
  ownerId,
  incoming,
  providerTasks = [],
  providerGetTask,
  options = {},
  } = configuration;
  if (typeof serviceRest !== "function") throw new Error("serviceRest is required");
  const owner = clean(ownerId, 100);
  if (!owner) throw new Error("ownerId is required");
  const profile = extractIntentProfile(incoming || {});
  let projectGoalId = null;
  if (profile.project_id) {
    const projectQuery = new URLSearchParams({
      owner_id: `eq.${owner}`,
      id: `eq.${profile.project_id}`,
      select: "id,goal_plan_id",
      limit: "1",
    });
    const project = (await serviceRest(`projects?${projectQuery}`))?.[0];
    if (!project?.id) throw new Error(`Project was not found: ${profile.project_id}`);
    projectGoalId = project.goal_plan_id || null;
    if (profile.goal_plan_id && profile.goal_plan_id !== projectGoalId) {
      throw new Error("Project does not belong to the supplied Goal");
    }
  }
  const effectiveGoalId = profile.goal_plan_id || projectGoalId;
  const goalQuery = new URLSearchParams({
    owner_id: `eq.${owner}`,
    status: "not.in.(Completed,Dropped,Archived)",
    select: "id,title,description,why,notes,status,updated_at",
    order: "updated_at.desc",
    limit: String(Math.max(1, Math.min(200, Number(options.goalLimit || 100)))),
  });
  if (effectiveGoalId) goalQuery.set("id", `eq.${effectiveGoalId}`);
  const [profiles, goals] = await Promise.all([
    serviceRest("rpc/search_task_resolution_profiles", {
      method: "POST",
      body: JSON.stringify({
        target_owner: owner,
        query_text: profile.normalized_text,
        query_entities: profile.entities,
        query_topics: profile.topics,
        query_resources: profile.resources,
        match_count: Math.max(1, Math.min(50, Number(options.profileLimit || 20))),
      }),
    }),
    serviceRest(`goals_plans?${goalQuery}`),
  ]);
  if (effectiveGoalId && !goals?.some((goal) => String(goal.id) === effectiveGoalId)) {
    throw new Error(`Goal was not found or is closed: ${effectiveGoalId}`);
  }
  const knownIds = new Set(providerTasks.map(taskId));
  const hydrated = [];
  const explicitDependencyIds = uniqueStrings(incoming?.depends_on_task_ids || incoming?.dependsOnTaskIds || []);
  const missingExplicitIds = explicitDependencyIds.filter((id) => !knownIds.has(id));
  if (missingExplicitIds.length && typeof providerGetTask !== "function") {
    throw new Error("providerGetTask is required to validate explicit Task dependencies");
  }
  for (const id of missingExplicitIds) {
    const task = await providerGetTask(id);
    if (!taskId(task)) throw new Error(`Explicit prerequisite Task was not found: ${id}`);
    hydrated.push(task);
    knownIds.add(taskId(task));
  }
  const missingProfileIds = uniqueStrings((profiles || []).map((item) => item.google_task_id))
    .filter((id) => !knownIds.has(id));
  if (missingProfileIds.length && typeof providerGetTask === "function") {
    const results = await Promise.allSettled(missingProfileIds.map((id) => providerGetTask(id)));
    for (const result of results) {
      if (result.status === "fulfilled" && taskId(result.value)) hydrated.push(result.value);
    }
  }
  return {
    ...buildTaskResolutionContext([...providerTasks, ...hydrated], profiles || [], goals || [], options),
    project_goal_id: projectGoalId,
  };
}

/**
 * PostgREST-backed metadata adapter. Provider Task reads/writes stay injectable so
 * Google Tasks remains the canonical content and completion store.
 */
export function createTaskResolutionAdapter(options = {}) {
  const ownerId = clean(options.ownerId, 100);
  const taskListId = clean(options.taskListId, 1_024) || null;
  const serviceRest = options.serviceRest;
  const provider = options.provider || {};
  if (!ownerId) throw new Error("ownerId is required");
  if (typeof serviceRest !== "function") throw new Error("serviceRest is required");
  for (const method of ["getTask", "createTask", "updateTask"]) {
    if (typeof provider[method] !== "function") throw new Error(`provider.${method} is required`);
  }

  const patchOuterAudit = async (changes) => {
    if (!options.intakeAuditId) return;
    const query = new URLSearchParams({ id: `eq.${options.intakeAuditId}`, owner_id: `eq.${ownerId}` });
    await serviceRest(`personal_os_intake_audit?${query}`, {
      method: "PATCH",
      headers: { Prefer: "return=minimal" },
      body: JSON.stringify(changes),
    });
  };

  const upsertContextLink = async (googleTaskId, goalPlanId = null, projectId = null) => {
    const existingQuery = new URLSearchParams({
      owner_id: `eq.${ownerId}`,
      google_task_id: `eq.${googleTaskId}`,
      select: "goal_plan_id,project_id",
      limit: "1",
    });
    const current = (await serviceRest(`task_context_links?${existingQuery}`))?.[0] || {};
    const requestedProjectId = projectId || options.projectId || null;
    const requestedGoalId = goalPlanId || options.projectGoalId || null;
    const resolvedGoalId = requestedProjectId
      ? requestedGoalId
      : requestedGoalId || current.goal_plan_id || null;
    const resolvedProjectId = requestedProjectId
      || (current.goal_plan_id === resolvedGoalId ? current.project_id : null)
      || null;
    if (!resolvedGoalId && !resolvedProjectId) return null;
    const rows = await serviceRest("task_context_links?on_conflict=owner_id%2Cgoogle_task_id&select=*", {
      method: "POST",
      headers: { Prefer: "resolution=merge-duplicates,return=representation" },
      body: JSON.stringify({
        owner_id: ownerId,
        google_task_id: googleTaskId,
        goal_plan_id: resolvedGoalId,
        project_id: resolvedProjectId,
      }),
    });
    return rows?.[0] || null;
  };

  return {
    getTask: (id) => provider.getTask(id),
    async findExistingResolution() {
      if (!options.resolutionIdempotencyKey) return null;
      const query = new URLSearchParams({ owner_id: `eq.${ownerId}`, idempotency_key: `eq.${options.resolutionIdempotencyKey}`, select: "*", limit: "1" });
      return (await serviceRest(`task_resolution_audit?${query}`))?.[0] || null;
    },
    createTask: (task, metadata) => provider.createTask(task, metadata),
    updateTask: (id, changes, metadata) => provider.updateTask(id, changes, metadata),

    async startResolutionAudit(audit, plan) {
      const rows = await serviceRest("task_resolution_audit?select=*", {
        method: "POST",
        headers: { Prefer: "return=representation" },
        body: JSON.stringify(resolutionAuditPayload(ownerId, audit, plan, options)),
      });
      if (!rows?.[0]?.id) throw new Error("Resolution audit insert returned no id");
      return rows[0];
    },

    async completeResolutionAudit(id, changes) {
      const query = new URLSearchParams({ id: `eq.${id}`, owner_id: `eq.${ownerId}` });
      const rows = await serviceRest(`task_resolution_audit?${query}&select=*`, {
        method: "PATCH",
        headers: { Prefer: "return=representation" },
        body: JSON.stringify(changes),
      });
      await patchOuterAudit({
        resolution_audit_id: id,
        resolution_decision: rows?.[0]?.decision || null,
        resolution_confidence: rows?.[0]?.confidence ?? null,
        resolution_reason: rows?.[0]?.reason || null,
      });
      return rows?.[0] || null;
    },

    async failResolutionAudit(id, changes) {
      const query = new URLSearchParams({ id: `eq.${id}`, owner_id: `eq.${ownerId}` });
      await serviceRest(`task_resolution_audit?${query}`, {
        method: "PATCH",
        headers: { Prefer: "return=minimal" },
        body: JSON.stringify(changes),
      });
      await patchOuterAudit({ resolution_audit_id: id });
    },

    async upsertTaskProfile(profile, metadata = {}) {
      const profileQuery = new URLSearchParams({
        owner_id: `eq.${ownerId}`,
        google_task_id: `eq.${profile.google_task_id}`,
        select: "canonical_task_id,entities,topics,resources,read_resources,write_resources,resource_fields,source_intent_ids,goal_plan_id,project_id,created_from",
        limit: "1",
      });
      const current = (await serviceRest(`task_resolution_profiles?${profileQuery}`))?.[0] || {};
      const sourceIntentIds = uniqueStrings([
        ...(current.source_intent_ids || []),
        ...(profile.source_intent_ids || []),
        metadata.resolution_audit_id,
      ]);
      const requestedProjectId = profile.project_id || options.projectId || null;
      const requestedGoalId = profile.goal_plan_id || (requestedProjectId ? options.projectGoalId || null : null);
      const resolvedGoalId = requestedProjectId
        ? requestedGoalId
        : requestedGoalId || current.goal_plan_id || null;
      const goalChanged = Boolean(requestedGoalId && requestedGoalId !== current.goal_plan_id);
      const mergedProfile = {
        ...profile,
        canonical_task_id: profile.canonical_task_id || current.canonical_task_id || profile.google_task_id,
        entities: uniqueStrings([...(current.entities || []), ...(profile.entities || [])]),
        topics: uniqueStrings([...(current.topics || []), ...(profile.topics || [])]),
        resources: uniqueStrings([...(current.resources || []), ...(profile.resources || [])]),
        read_resources: uniqueStrings([...(current.read_resources || []), ...(profile.read_resources || [])]),
        write_resources: uniqueStrings([...(current.write_resources || []), ...(profile.write_resources || [])]),
        resource_fields: uniqueStrings([...(current.resource_fields || []), ...(profile.resource_fields || [])]),
        goal_plan_id: resolvedGoalId,
        project_id: requestedProjectId || (goalChanged ? null : current.project_id) || null,
      };
      const rows = await serviceRest("task_resolution_profiles?on_conflict=owner_id%2Cgoogle_task_id&select=*", {
        method: "POST",
        headers: { Prefer: "resolution=merge-duplicates,return=representation" },
        body: JSON.stringify({
          owner_id: ownerId,
          task_list_id: taskListId,
          created_from: current.created_from || options.createdFrom || "personal_os_intake",
          ...mergedProfile,
          source_intent_ids: sourceIntentIds,
        }),
      });
      const scheduleQuery = new URLSearchParams({ owner_id: `eq.${ownerId}`, google_task_id: `eq.${profile.google_task_id}` });
      await serviceRest(`task_schedule_metadata?${scheduleQuery}`, {
        method: "PATCH",
        headers: { Prefer: "return=minimal" },
        body: JSON.stringify({
          canonical_task_id: profile.canonical_task_id || profile.google_task_id,
          resolution_confidence: profile.resolution_confidence ?? null,
          resolution_reason: profile.resolution_reason || null,
          created_from: current.created_from || options.createdFrom || "personal_os_intake",
          last_semantic_resolution_at: profile.last_semantic_resolution_at,
        }),
      });
      return rows?.[0] || null;
    },

    async upsertRelationships(relationships, metadata = {}) {
      const query = new URLSearchParams({
        owner_id: `eq.${ownerId}`,
        active: "eq.true",
        superseded_at: "is.null",
        select: "*",
        limit: "1000",
      });
      const existing = await serviceRest(`task_relationships?${query}`) || [];
      const accepted = [];
      for (const relationship of relationships.map(canonicalRelationship)) {
        const validated = validateTaskRelationship(relationship, [...existing, ...accepted]);
        accepted.push({
          owner_id: ownerId,
          ...validated,
          source_intent_id: validated.source_intent_id || metadata.resolution_audit_id || null,
          active: true,
          superseded_at: null,
        });
      }
      if (!accepted.length) return [];
      return serviceRest("task_relationships?on_conflict=owner_id%2Cfrom_task_id%2Cto_task_id%2Crelationship_type&select=*", {
        method: "POST",
        headers: { Prefer: "resolution=merge-duplicates,return=representation" },
        body: JSON.stringify(accepted),
      });
    },

    async upsertResourceBindings(bindings, metadata = {}) {
      if (!bindings.length) return [];
      const taskIds = uniqueStrings(bindings.map((binding) => binding.google_task_id));
      const existing = [];
      for (const googleTaskId of taskIds) {
        const query = new URLSearchParams({
          owner_id: `eq.${ownerId}`,
          google_task_id: `eq.${googleTaskId}`,
          select: "google_task_id,resource_key,access_type,fields",
        });
        existing.push(...((await serviceRest(`task_resource_bindings?${query}`)) || []));
      }
      const byKey = new Map(existing.map((binding) => [
        `${binding.google_task_id}:${binding.resource_key}`,
        binding,
      ]));
      return serviceRest("task_resource_bindings?on_conflict=owner_id%2Cgoogle_task_id%2Cresource_key&select=*", {
        method: "POST",
        headers: { Prefer: "resolution=merge-duplicates,return=representation" },
        body: JSON.stringify(bindings.map((binding) => {
          const current = byKey.get(`${binding.google_task_id}:${binding.resource_key}`) || {};
          return {
            owner_id: ownerId,
            ...binding,
            access_type: mergedResourceAccess(current.access_type, binding.access_type),
            fields: uniqueStrings([...(current.fields || []), ...(binding.fields || [])]),
            source_intent_id: binding.source_intent_id || metadata.resolution_audit_id || null,
          };
        })),
      });
    },

    linkContext: upsertContextLink,
    linkGoal: (googleTaskId, goalPlanId) => upsertContextLink(googleTaskId, goalPlanId, options.projectId || null),
  };
}

export async function resolveAndExecuteTask(incoming, context, adapter) {
  const previous = typeof adapter.findExistingResolution === "function" ? await adapter.findExistingResolution() : null;
  if (previous) {
    const ids = previous.result_task_ids || [];
    if (previous.status !== "succeeded" || !ids.length) {
      const error = new Error("Previous write requires reconciliation; do not create another task");
      error.code = "RESOLUTION_RECOVERY_REQUIRED";
      error.task_ids = ids;
      throw error;
    }
    const tasks = await Promise.all(ids.map((id) => adapter.getTask(id)));
    if (tasks.some((task, index) => taskId(task) !== ids[index])) throw new Error("Previous resolution task cannot be verified");
    return {
      success: true, task: tasks[0], tasks, created: false, updated: false, reused: true, replayed: true,
      resolution: { decision: "DUPLICATE", original_decision: previous.decision, audit_id: previous.id, confidence: previous.confidence, reason: "Verified replay of the existing resolution result" },
      relationships: [], goal_link: null, context_link: null,
    };
  }
  const resolution = resolveTaskIntent(incoming, context);
  return executeTaskResolution(incoming, resolution, adapter);
}

export function taskResolutionPreview(incoming, context) {
  const resolution = resolveTaskIntent(incoming, context);
  return {
    ...resolution,
    normalized_intent: extractIntentProfile(incoming),
    preview: true,
    persisted: false,
  };
}

const COMPLETE_STATUSES = new Set(["completed", "done"]);
const INACTIVE_STATUSES = new Set(["deleted", "cancelled", "archived"]);

function clean(value) {
  return typeof value === "string" ? value.trim() : "";
}

function idOf(task) {
  return clean(task?.task_id || task?.google_task_id || task?.id || task?.externalId);
}

function statusOf(task) {
  return clean(task?.status).toLowerCase() || (task?.done ? "completed" : "open");
}

function relationType(item) {
  return clean(item?.relationship_type || item?.type).toUpperCase();
}

function fromId(item) {
  return clean(item?.from_task_id || item?.source_task_id || item?.from);
}

function toId(item) {
  return clean(item?.to_task_id || item?.target_task_id || item?.to);
}

function activeRelation(item) {
  return item?.active !== false && item?.superseded_at == null;
}

function sorted(values) {
  return [...values].sort((left, right) => String(left).localeCompare(String(right), "zh-CN", { numeric: true }));
}

function dependencyPairs(relationships) {
  return relationships
    .filter((item) => activeRelation(item) && relationType(item) === "DEPENDS_ON")
    .map((item) => ({ dependent: fromId(item), prerequisite: toId(item), relationship: item }))
    .filter((item) => item.dependent && item.prerequisite && item.dependent !== item.prerequisite);
}

function parentPairs(relationships) {
  return relationships
    .filter((item) => activeRelation(item) && relationType(item) === "PARENT_OF")
    .map((item) => ({ parent: fromId(item), child: toId(item), relationship: item }))
    .filter((item) => item.parent && item.child && item.parent !== item.child);
}

function conflictPairs(relationships) {
  return relationships
    .filter((item) => activeRelation(item) && relationType(item) === "CONFLICTS_WITH")
    .map((item) => ({ left: fromId(item), right: toId(item), relationship: item }))
    .filter((item) => item.left && item.right && item.left !== item.right);
}

function uniqueRelations(relationships = []) {
  const seen = new Set();
  const result = [];
  for (const item of relationships) {
    const type = relationType(item);
    const from = fromId(item);
    const to = toId(item);
    if (!type || !from || !to || from === to) continue;
    const symmetric = ["RELATED_TO", "POTENTIAL_RELATION", "CONFLICTS_WITH", "SHARES_RESOURCE"].includes(type);
    const endpoints = symmetric ? sorted([from, to]) : [from, to];
    const key = `${type}:${endpoints[0]}:${endpoints[1]}`;
    if (seen.has(key)) continue;
    seen.add(key);
    result.push({ ...item, relationship_type: type, from_task_id: from, to_task_id: to });
  }
  return result;
}

function pathExists(start, target, adjacency, visited = new Set()) {
  if (start === target) return true;
  if (visited.has(start)) return false;
  visited.add(start);
  for (const next of adjacency.get(start) || []) if (pathExists(next, target, adjacency, visited)) return true;
  return false;
}

export function relationshipWouldCreateCycle(relationships, dependentTaskId, prerequisiteTaskId) {
  const dependent = clean(dependentTaskId);
  const prerequisite = clean(prerequisiteTaskId);
  if (!dependent || !prerequisite || dependent === prerequisite) return true;
  const adjacency = new Map();
  for (const pair of dependencyPairs(uniqueRelations(relationships))) {
    if (!adjacency.has(pair.dependent)) adjacency.set(pair.dependent, new Set());
    adjacency.get(pair.dependent).add(pair.prerequisite);
  }
  return pathExists(prerequisite, dependent, adjacency);
}

export function validateTaskRelationship(relationship, existing = []) {
  const type = relationType(relationship);
  const from = fromId(relationship);
  const to = toId(relationship);
  if (!type || !from || !to) throw new Error("relationship_type, from_task_id, and to_task_id are required");
  if (from === to) throw new Error("A task cannot relate to itself");
  if (type === "DEPENDS_ON" && relationshipWouldCreateCycle(existing, from, to)) {
    throw new Error("Dependency would create a cycle");
  }
  return { ...relationship, relationship_type: type, from_task_id: from, to_task_id: to };
}

function transitiveDependencyMap(taskIds, dependencies) {
  const direct = new Map(taskIds.map((id) => [id, new Set()]));
  for (const pair of dependencies) {
    if (!direct.has(pair.dependent)) direct.set(pair.dependent, new Set());
    direct.get(pair.dependent).add(pair.prerequisite);
  }
  const closure = new Map();
  const walk = (id, visited = new Set()) => {
    if (visited.has(id)) return visited;
    visited.add(id);
    for (const prerequisite of direct.get(id) || []) walk(prerequisite, visited);
    return visited;
  };
  for (const id of taskIds) {
    const values = walk(id, new Set());
    values.delete(id);
    closure.set(id, values);
  }
  return closure;
}

function shareConflict(left, right, conflicts) {
  return conflicts.some((pair) => (pair.left === left && pair.right === right) || (pair.left === right && pair.right === left));
}

function writeResources(task) {
  return new Set(task?.write_resources || task?.writes || task?.semantic_profile?.write_resources || []);
}

function hasSharedWrite(left, right) {
  const a = writeResources(left);
  const b = writeResources(right);
  for (const value of a) if (b.has(value)) return true;
  return false;
}

export function canTasksRunInParallel(leftTask, rightTask, relationships = []) {
  const left = idOf(leftTask);
  const right = idOf(rightTask);
  if (!left || !right || left === right) return false;
  const unique = uniqueRelations(relationships);
  const dependencies = dependencyPairs(unique);
  const closure = transitiveDependencyMap([left, right, ...dependencies.flatMap((pair) => [pair.dependent, pair.prerequisite])], dependencies);
  if (closure.get(left)?.has(right) || closure.get(right)?.has(left)) return false;
  if (shareConflict(left, right, conflictPairs(unique))) return false;
  return !hasSharedWrite(leftTask, rightTask);
}

function topologicalLayers(taskIds, dependencies) {
  const ids = new Set(taskIds);
  const outgoing = new Map(taskIds.map((id) => [id, new Set()]));
  const indegree = new Map(taskIds.map((id) => [id, 0]));
  for (const { dependent, prerequisite } of dependencies) {
    if (!ids.has(dependent) || !ids.has(prerequisite)) continue;
    if (!outgoing.get(prerequisite).has(dependent)) {
      outgoing.get(prerequisite).add(dependent);
      indegree.set(dependent, (indegree.get(dependent) || 0) + 1);
    }
  }
  const layers = [];
  let frontier = sorted([...ids].filter((id) => indegree.get(id) === 0));
  const consumed = new Set();
  while (frontier.length) {
    layers.push(frontier);
    const next = new Set();
    for (const id of frontier) {
      consumed.add(id);
      for (const dependent of outgoing.get(id) || []) {
        indegree.set(dependent, indegree.get(dependent) - 1);
        if (indegree.get(dependent) === 0) next.add(dependent);
      }
    }
    frontier = sorted(next);
  }
  return { layers, cyclic: sorted([...ids].filter((id) => !consumed.has(id))) };
}

function partitionParallel(taskIds, nodeById, relationships) {
  const groups = [];
  for (const id of taskIds) {
    const task = nodeById.get(id)?.task;
    let placed = false;
    for (const group of groups) {
      if (group.every((otherId) => canTasksRunInParallel(task, nodeById.get(otherId)?.task, relationships))) {
        group.push(id);
        placed = true;
        break;
      }
    }
    if (!placed) groups.push([id]);
  }
  return groups;
}

export function buildTaskExecutionGraph(tasks = [], relationships = []) {
  const unique = uniqueRelations(relationships);
  const nodeById = new Map();
  for (const task of tasks) {
    const id = idOf(task);
    if (!id || INACTIVE_STATUSES.has(statusOf(task))) continue;
    nodeById.set(id, {
      id,
      title: clean(task.title),
      status: statusOf(task),
      execution_status: "READY",
      blocked_by: [],
      depends_on: [],
      parent_task_id: null,
      child_task_ids: [],
      related_task_ids: [],
      conflict_task_ids: [],
      shared_resources: [],
      goal_plan_id: clean(task.goal_plan_id || task.goal_id) || null,
      project_id: clean(task.project_id) || null,
      canonical_task_id: clean(task.canonical_task_id) || id,
      task,
    });
  }

  const dependencies = dependencyPairs(unique);
  const parents = parentPairs(unique);
  const conflicts = conflictPairs(unique);
  for (const pair of dependencies) {
    const dependent = nodeById.get(pair.dependent);
    if (!dependent) continue;
    dependent.depends_on.push(pair.prerequisite);
    const prerequisite = nodeById.get(pair.prerequisite);
    if (!prerequisite || !COMPLETE_STATUSES.has(prerequisite.status)) dependent.blocked_by.push(pair.prerequisite);
  }
  for (const pair of parents) {
    const parent = nodeById.get(pair.parent);
    const child = nodeById.get(pair.child);
    if (parent) parent.child_task_ids.push(pair.child);
    if (child) child.parent_task_id = pair.parent;
  }
  for (const pair of conflicts) {
    const left = nodeById.get(pair.left);
    const right = nodeById.get(pair.right);
    if (left) left.conflict_task_ids.push(pair.right);
    if (right) right.conflict_task_ids.push(pair.left);
  }
  for (const item of unique) {
    const type = relationType(item);
    const from = nodeById.get(fromId(item));
    const to = nodeById.get(toId(item));
    if (["RELATED_TO", "POTENTIAL_RELATION"].includes(type)) {
      if (from) from.related_task_ids.push(toId(item));
      if (to) to.related_task_ids.push(fromId(item));
    }
    if (type === "SHARES_RESOURCE") {
      const resource = clean(item?.metadata?.resource || item?.resource_key);
      if (resource && from) from.shared_resources.push(resource);
      if (resource && to) to.shared_resources.push(resource);
    }
  }

  for (const node of nodeById.values()) {
    node.blocked_by = sorted(new Set(node.blocked_by));
    node.depends_on = sorted(new Set(node.depends_on));
    node.child_task_ids = sorted(new Set(node.child_task_ids));
    node.related_task_ids = sorted(new Set(node.related_task_ids));
    node.conflict_task_ids = sorted(new Set(node.conflict_task_ids));
    node.shared_resources = sorted(new Set(node.shared_resources));
    if (COMPLETE_STATUSES.has(node.status)) node.execution_status = "COMPLETED";
    else if (node.blocked_by.length) node.execution_status = "BLOCKED";
    else if (node.conflict_task_ids.some((id) => {
      const other = nodeById.get(id);
      return other && !COMPLETE_STATUSES.has(other.status);
    })) node.execution_status = "CONFLICT";
    else if (node.status === "waiting") node.execution_status = "WAITING";
    else node.execution_status = "READY";
  }

  const openIds = [...nodeById.values()]
    .filter((node) => !COMPLETE_STATUSES.has(node.status))
    .map((node) => node.id);
  const topology = topologicalLayers(openIds, dependencies);
  const executionLayers = topology.layers.map((ids, index) => ({
    index,
    task_ids: ids,
    parallel_groups: partitionParallel(ids, nodeById, unique),
  }));
  const nodes = [...nodeById.values()].map(({ task: _task, ...node }) => node)
    .sort((left, right) => left.id.localeCompare(right.id));
  return {
    nodes,
    relationships: unique,
    execution_layers: executionLayers,
    ready_task_ids: nodes.filter((node) => node.execution_status === "READY").map((node) => node.id),
    blocked_task_ids: nodes.filter((node) => node.execution_status === "BLOCKED").map((node) => node.id),
    waiting_task_ids: nodes.filter((node) => node.execution_status === "WAITING").map((node) => node.id),
    conflict_task_ids: nodes.filter((node) => node.execution_status === "CONFLICT").map((node) => node.id),
    completed_task_ids: nodes.filter((node) => node.execution_status === "COMPLETED").map((node) => node.id),
    cyclic_task_ids: topology.cyclic,
    valid_dag: topology.cyclic.length === 0,
  };
}

import { verifyTaskFields } from "./write-receipt.js";
import {
  INCOMING_TASK_REF,
  RESOLUTION_THRESHOLDS,
  buildResolutionMutationPlan,
  replaceIncomingTaskRefs,
  resolutionProfileRecord,
} from "./task-resolution-engine.js";

function requireMethod(adapter, name) {
  if (typeof adapter?.[name] !== "function") throw new Error(`Resolution adapter must implement ${name}()`);
  return adapter[name].bind(adapter);
}

function taskId(task) {
  return String(task?.task_id || task?.google_task_id || task?.id || "").trim();
}

function resultTask(value) {
  return value?.task && typeof value.task === "object" ? value.task : value;
}

function resourceBindings(task, profile, sourceIntentId) {
  return profile.resources.map((resource) => {
    const reads = profile.read_resources.includes(resource);
    const writes = profile.write_resources.includes(resource);
    return {
      google_task_id: taskId(task),
      resource_key: resource,
      access_type: reads && writes ? "read_write" : writes ? "write" : "read",
      fields: profile.resource_fields,
      source_intent_id: sourceIntentId,
    };
  });
}

export async function executeTaskResolution(incoming, resolution, adapter) {
  if (resolution.requires_clarification === true || (["UPDATE", "MERGE"].includes(resolution.decision)
    && !(Number.isFinite(resolution.confidence) && resolution.confidence >= RESOLUTION_THRESHOLDS.automatic))) {
    const error = new Error(resolution.reason || "Multiple tasks match; choose the intended task");
    error.code = "TASK_TARGET_AMBIGUOUS";
    throw error;
  }
  const plan = buildResolutionMutationPlan(incoming, resolution);
  const startAudit = requireMethod(adapter, "startResolutionAudit");
  const completeAudit = requireMethod(adapter, "completeResolutionAudit");
  const failAudit = requireMethod(adapter, "failResolutionAudit");
  const getTask = requireMethod(adapter, "getTask");
  const createTask = requireMethod(adapter, "createTask");
  const updateTask = requireMethod(adapter, "updateTask");
  const upsertProfile = requireMethod(adapter, "upsertTaskProfile");
  const upsertRelationships = requireMethod(adapter, "upsertRelationships");
  const upsertResources = requireMethod(adapter, "upsertResourceBindings");
  const linkContext = typeof adapter.linkContext === "function" ? adapter.linkContext.bind(adapter) : null;
  const linkGoal = typeof adapter.linkGoal === "function" ? adapter.linkGoal.bind(adapter) : null;

  const audit = await startAudit(plan.audit, plan);
  const auditId = String(audit?.id || audit?.audit_id || audit || "").trim();
  if (!auditId) throw new Error("Resolution audit did not return an id");

  async function readWrittenTask(written, expected) {
    const current = resultTask(await getTask(taskId(written)));
    if (!current || taskId(current) !== taskId(written)) {
      const error = new Error("Task write result requires readback reconciliation");
      error.code = "WRITE_UNVERIFIED";
      throw error;
    }
    verifyTaskFields(current, expected);
    return current;
  }
  const createdByTempId = {};
  const resultingTasks = [];
  let previousState = null;
  try {
    for (const operation of plan.operations) {
      if (operation.type === "reuse") {
        const task = resultTask(await getTask(operation.task_id));
        if (!taskId(task)) throw new Error("Canonical task was not found during duplicate reuse");
        previousState = task;
        resultingTasks.push(task);
        continue;
      }
      if (operation.type === "update") {
        previousState = resultTask(await getTask(operation.task_id));
        const task = resultTask(await updateTask(operation.task_id, operation.changes, {
          decision: plan.decision,
          confidence: plan.confidence,
          resolution_audit_id: auditId,
        }));
        if (!taskId(task)) throw new Error("Task update did not return the canonical task");
        resultingTasks.push(task);
        resultingTasks[resultingTasks.length - 1] = await readWrittenTask(task, operation.changes);
        continue;
      }
      if (operation.type === "create") {
        const parentTaskId = operation.parent_temp_id
          ? taskId(createdByTempId[operation.parent_temp_id])
          : null;
        if (operation.parent_temp_id && !parentTaskId) throw new Error("Parent task must be created before its child");
        const task = resultTask(await createTask(operation.task, {
          parent_task_id: parentTaskId,
          decision: plan.decision,
          confidence: plan.confidence,
          resolution_audit_id: auditId,
        }));
        if (!taskId(task)) throw new Error("Task creation did not return a provider id");
        resultingTasks.push(task); // retain the provider id even if readback fails
        const verified = await readWrittenTask(task, operation.task);
        createdByTempId[operation.temp_id] = verified;
        resultingTasks[resultingTasks.length - 1] = verified;
      }
    }

    const primaryTask = createdByTempId[INCOMING_TASK_REF] || resultingTasks[0];
    const primaryTaskId = taskId(primaryTask);
    const childIds = Object.fromEntries(Object.entries(createdByTempId).map(([tempId, task]) => [tempId, taskId(task)]));
    const relationships = replaceIncomingTaskRefs(plan.relationships, primaryTaskId, childIds)
      .filter((item) => item.from_task_id !== item.to_task_id)
      .map((item) => ({ ...item, source_intent_id: auditId }));

    const contextLink = {
      goal_plan_id: plan.goal_link?.goal_id || incoming.goal_plan_id || incoming.goal_id || null,
      project_id: incoming.project_id || incoming.projectId || null,
    };
    if ((contextLink.goal_plan_id || contextLink.project_id) && (linkContext || linkGoal)) {
      for (const task of resultingTasks) {
        if (linkContext) {
          await linkContext(taskId(task), contextLink.goal_plan_id, contextLink.project_id, { resolution_audit_id: auditId });
        } else if (contextLink.goal_plan_id) {
          await linkGoal(taskId(task), contextLink.goal_plan_id, { resolution_audit_id: auditId });
        }
      }
    }

    for (const task of resultingTasks) {
      const profile = resolutionProfileRecord({
        ...task,
        canonical_task_id: resolution.canonical_task_id || task.canonical_task_id || taskId(task),
        goal_plan_id: plan.goal_link?.goal_id || task.goal_plan_id || incoming.goal_plan_id || incoming.goal_id || null,
        project_id: task.project_id || incoming.project_id || null,
        read_resources: task.read_resources || incoming.read_resources || incoming.reads || [],
        write_resources: task.write_resources || incoming.write_resources || incoming.writes || [],
        resource_fields: task.resource_fields || incoming.resource_fields || incoming.fields || [],
      }, resolution);
      profile.source_intent_ids = [auditId];
      await upsertProfile(profile, { resolution_audit_id: auditId });
      await upsertResources(resourceBindings(task, profile, auditId), { resolution_audit_id: auditId });
    }
    if (relationships.length) await upsertRelationships(relationships, { resolution_audit_id: auditId });

    const finalAudit = {
      status: "succeeded",
      previous_state: previousState,
      new_state: resultingTasks,
      result_task_ids: resultingTasks.map(taskId),
      canonical_task_id: resolution.canonical_task_id || primaryTaskId || resolution.existing_task_id || null,
      related_object_ids: {
        ...plan.audit.related_object_ids,
        task_ids: [...new Set([
          ...(plan.audit.related_object_ids.task_ids || []),
          ...resultingTasks.map(taskId),
        ])],
      },
    };
    await completeAudit(auditId, finalAudit);
    return {
      success: true,
      resolution: {
        decision: plan.decision,
        confidence: plan.confidence,
        reason: plan.reason,
        audit_id: auditId,
        non_destructive: true,
      },
      task: primaryTask,
      tasks: resultingTasks,
      relationships,
      goal_link: plan.goal_link,
      context_link: contextLink.goal_plan_id || contextLink.project_id ? contextLink : null,
      created: plan.operations.some((item) => item.type === "create"),
      updated: plan.operations.some((item) => item.type === "update"),
      reused: plan.operations.some((item) => item.type === "reuse"),
    };
  } catch (error) {
    const failure = {
      status: "failed",
      error: error instanceof Error ? error.message : "Task resolution execution failed",
      previous_state: previousState,
      new_state: resultingTasks,
      result_task_ids: resultingTasks.map(taskId),
    };
    try { await failAudit(auditId, failure); } catch { /* Preserve the original failure. */ }
    if (error && typeof error === "object") error.partial_result = failure;
    throw error;
  }
}

